window.BIOMASTER.MCQ_PHYSIOLOGY = [{"id":"MCQ-PH-001","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh lý Thực vật","q":"Để tổng hợp được 1 phân tử Glucose ($C_6H_{12}O_6$) trong pha tối quang hợp, thực vật $C_3$ và thực vật $C_4$ cần tiêu tốn tối thiểu bao nhiêu phân tử ATP?","opts":["$C_3$ cần $18\\text{ ATP}$, $C_4$ cần $30\\text{ ATP}$.","$C_3$ cần $18\\text{ ATP}$, $C_4$ cần $24\\text{ ATP}$.","$C_3$ cần $12\\text{ ATP}$, $C_4$ cần $18\\text{ ATP}$.","Cả hai đều cần $18\\text{ ATP}$."],"ans":0,"exp":"$C_3$ cần $18\\text{ ATP}$; $C_4$ cần thêm $12\\text{ ATP}$ tái tạo PEP $\\Rightarrow 30\\text{ ATP}$."},{"id":"MCQ-PH-002","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh lý Động vật","q":"Khi cơ thể hoạt động cơ bắp mạnh làm $pCO_2$ trong máu tăng cao và pH máu giảm, đường cong phân ly $Hb-O_2$ thay đổi như thế nào (Hiệu ứng Bohr)?","opts":["Dịch chuyển sang trái, làm tăng ái lực của Hb với $O_2$.","Làm Hemoglobin biến tính hoàn toàn.","Dịch chuyển sang phải, làm giảm ái lực của Hb với $O_2$ giúp tăng giải phóng $O_2$ cho mô.","Không thay đổi vị trí."],"ans":2,"exp":"Hiệu ứng Bohr: $pCO_2$ cao, pH thấp làm đường cong dịch phải, tăng nhường $O_2$ cho mô."},{"id":"MCQ-PH-003","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dinh dưỡng Nitơ ở TV","q":"Thực vật bậc cao chỉ có thể hấp thụ trực tiếp Nitơ từ đất qua rễ dưới hai dạng ion khoáng nào sau đây?","opts":["Protein và amino acid chưa phân giải.","Ion Ammonium ($NH_4^+$) và ion Nitrate ($NO_3^-$).","Khí $N_2$ và $NH_3$.","Ion Nitrite ($NO_2^-$) và khí $N_2$."],"ans":1,"exp":"Rễ cây chỉ hấp thụ Nitơ khoáng dưới hai dạng là $NH_4^+$ và $NO_3^-$."},{"id":"MCQ-PH-004","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hormone Thực vật","q":"Cặp hormone thực vật nào sau đây có tác dụng đối kháng nhau trong việc điều khiển sự ngủ nghỉ và nảy mầm của hạt (một chất kích thích nảy mầm, một chất ức chế duy trì trạng thái ngủ)?","opts":["Ethylene và Auxin.","Cytokinin và Ethylene.","Gibberellin (GA) và Acid Abscisic (ABA).","Auxin và Cytokinin."],"ans":2,"exp":"Tỉ lệ $GA / ABA$ quyết định sự nảy mầm của hạt: GA kích thích nảy mầm, ABA duy trì trạng thái ngủ."},{"id":"MCQ-PH-005","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hệ dẫn truyền tim","q":"Cấu trúc nào trong hệ dẫn truyền tự động của tim người đóng vai trò là nhạc trưởng phát nhịp chính với tần số cao nhất ($70 - 80\\text{ xung/phút}$)?","opts":["Nút xoang nhĩ (SA node - nằm ở thành tâm nhĩ phải).","Mạng lưới Purkinje.","Bó His.","Nút nhĩ thất (AV node)."],"ans":0,"exp":"Nút xoang nhĩ (SA) tự phát xung điện với tần số cao nhất nên dẫn nhịp cho toàn bộ quả tim."},{"id":"MCQ-PH-006","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quan hệ Sinh thái","q":"Mối quan hệ giữa vi khuẩn <i>Rhizobium</i> trong nốt sần rễ cây họ Đậu và cây họ Đậu, hoặc giữa nấm và vi khuẩn lam trong Địa y thuộc mối quan hệ sinh thái nào?","opts":["Cộng sinh (bắt buộc, cả hai cùng có lợi).","Hợp tác.","Hội sinh.","Ký sinh."],"ans":0,"exp":"Đây là mối quan hệ cộng sinh điển hình ($+ / +$ gắn bó chặt chẽ)."},{"id":"MCQ-PH-007","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thương số Hô hấp RQ","q":"Thương số hô hấp ($RQ = \\frac{\\text{Số mol } CO_2 \\text{ thải ra}}{\\text{Số mol } O_2 \\text{ hấp thụ}}$) khi hạt đang nảy mầm phân giải hoàn toàn nguyên liệu Carbohydrate (Glucose) bằng bao nhiêu?","opts":["$RQ = 1.0$.","$RQ = 1.3$.","$RQ = 0.8$.","$RQ = 0.7$."],"ans":0,"exp":"Phương trình: $C_6H_{12}O_6 + 6O_2 \\rightarrow 6CO_2 + 6H_2O \\Rightarrow RQ = \\frac{6}{6} = 1.0$."},{"id":"MCQ-PH-008","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thế nước Tế bào","q":"Một tế bào thực vật có thế chất tan $\\Psi_s = -0.9\\text{ MPa}$ và áp suất trương $\\Psi_p = +0.4\\text{ MPa}$ được nhúng vào một cốc dung dịch hở có thế nước $\\Psi_w = -0.3\\text{ MPa}$. Chiều di chuyển của nước và áp suất trương của tế bào khi đạt cân bằng là:","opts":["Nước đi từ dung dịch vào tế bào; khi cân bằng $\\Psi_p = +0.6\\text{ MPa}$.","Nước không di chuyển.","Tế bào bị co nguyên sinh hoàn toàn.","Nước đi từ tế bào ra dung dịch; $\\Psi_p = 0\\text{ MPa}$."],"ans":0,"exp":"$\\Psi_{w(\\text{tb})} = -0.5 < \\Psi_{w(\\text{dd})} = -0.3 \\rightarrow$ Nước đi vào tế bào đến khi $\\Psi_{w(\\text{mới})} = -0.3 \\Rightarrow \\Psi_p = +0.6\\text{ MPa}$."},{"id":"MCQ-PH-009","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang chu kỳ","q":"Một loài thực vật ngày ngắn (thời gian tối tới hạn 10 giờ) được đặt trong tối 12 giờ, nhưng ở giữa đêm tối bị chiếu chớp sáng theo thứ tự: Đỏ ($R$) $\\rightarrow$ Đỏ xa ($FR$) $\\rightarrow$ Đỏ ($R$). Cây này có ra hoa không?","opts":["Không ra hoa vì chớp sáng cuối cùng là ánh sáng Đỏ ($R, 660\\text{ nm}$) chuyển $P_r \\rightarrow P_{fr}$ phá vỡ đêm dài.","Có ra hoa.","Có ra hoa vì đã có tia $FR$.","Ra hoa 50%."],"ans":0,"exp":"Tia chiếu cuối cùng quyết định hiệu ứng: Tia $R$ tạo $P_{fr}$ ức chế cây ngày ngắn ra hoa."},{"id":"MCQ-PH-010","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hiệu suất Sinh thái","q":"Trong một hệ sinh thái, SVSX tích lũy được $10^7\\text{ kcal}$. SVTT bậc 1 tích lũy được $10^6\\text{ kcal}$, SVTT bậc 2 tích lũy được $8 \\times 10^4\\text{ kcal}$, SVTT bậc 3 tích lũy được $6.4 \\times 10^3\\text{ kcal}$. Hiệu suất sinh thái giữa bậc dinh dưỡng cấp 3 so với bậc dinh dưỡng cấp 2 là:","opts":["$12.5\\%$.","$8\\%$.","$6.4\\%$.","$10\\%$."],"ans":1,"exp":"Bậc dinh dưỡng cấp 2 là SVTT bậc 1 ($10^6\\text{ kcal}$); Bậc dinh dưỡng cấp 3 là SVTT bậc 2 ($8 \\times 10^4\\text{ kcal}$). Hiệu suất $= \\frac{8 \\times 10^4}{10^6} \\times 100\\% = 8\\%$."},{"id":"MCQ-PH-011","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa đường huyết","q":"Sau bữa ăn giàu tinh bột, nồng độ Glucose máu tăng cao sẽ kích thích tế bào nào của đảo tụy tiết hormone gì, và khi nhịn đói lâu ngày thì sao?","opts":["Tuyến thượng thận tiết Insulin.","Tế bào $\\alpha$ tiết Insulin; khi đói tế bào $\\beta$ tiết Glucagon.","Tế bào $\\beta$ tiết Insulin (chuyển Glucose thành Glycogen); khi đói tế bào $\\alpha$ tiết Glucagon (phân giải Glycogen thành Glucose).","Gan tiết Insulin và Glucagon."],"ans":2,"exp":"Tế bào $\\beta$ đảo tụy tiết Insulin làm hạ đường huyết; tế bào $\\alpha$ đảo tụy tiết Glucagon làm tăng đường huyết."},{"id":"MCQ-PH-012","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hệ đệm pH máu","q":"Khi một người bị hoảng loạn và thở quá nhanh, quá sâu (tăng thông khí phế nang quá mức), nồng độ $CO_2$ trong máu giảm mạnh sẽ dẫn đến rối loạn cân bằng acid - base nào sau đây ($CO_2 + H_2O \\rightleftharpoons H_2CO_3 \\rightleftharpoons H^+ + HCO_3^-$)?","opts":["Nhiễm kiềm hô hấp (pH máu tăng cao trên $7.45$ do cân bằng dịch chuyển sang trái làm giảm $[H^+]$).","Nhiễm toan chuyển hóa.","Nhiễm toan hô hấp (pH máu giảm thấp).","pH máu không hề thay đổi."],"ans":0,"exp":"Thở nhanh làm thải quá nhiều $CO_2 \\rightarrow$ cân bằng dịch chuyển theo chiều nghịch làm giảm nồng độ $[H^+]$ trong máu $\\rightarrow$ pH máu tăng cao (nhiễm kiềm hô hấp)."},{"id":"MCQ-PH-013","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Loài chủ chốt - Sinh thái","q":"Trong thí nghiệm của Robert Paine ở vùng triều Bắc Mỹ, khi loại bỏ loài sao biển săn mồi <i>Pisaster ochraceus</i> ra khỏi quần xã, số lượng loài trong quần xã đã giảm mạnh từ 15 loài xuống còn 8 loài. Loài sao biển <i>Pisaster</i> được gọi là:","opts":["Loài chủ chốt (Keystone species).","Loài đặc hữu.","Loài ưu thế (Dominant species).","Loài ngoại lai xâm lấn."],"ans":0,"exp":"Loài có sinh khối nhỏ nhưng giữ vai trò kiểm soát cấu trúc lưới thức ăn và duy trì đa dạng quần xã là Loài chủ chốt (Keystone species)."},{"id":"MCQ-PH-014","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ kinh nguyệt & Thuốc tránh thai","q":"Tại sao thuốc tránh thai hàng ngày (chứa nồng độ cao Estrogen và Progesterone tổng hợp) lại giúp ngăn cản sự rụng trứng ở phụ nữ?","opts":["Vì thuốc trực tiếp tiêu diệt tinh trùng trong tử cung.","Vì thuốc làm thể vàng bị thoái hóa ngay lập tức.","Vì thuốc kích thích tuyến yên tiết quá nhiều FSH và LH.","Vì nồng độ Progesterone và Estrogen cao duy trì liên tục gây ức chế ngược âm tính lên Vùng dưới đồi và Tuyến yên, làm giảm tiết GnRH, FSH và ngăn cản đỉnh LH (không có đỉnh LH thì trứng không chín và không rụng)."],"ans":3,"exp":"Nồng độ cao Estrogen + Progesterone ức chế ngược âm tính lên vùng dưới đồi - tuyến yên, kìm hãm tiết FSH và LH $\\rightarrow$ không có đỉnh LH giữa chu kỳ nên không xảy ra rụng trứng."},{"id":"MCQ-PH-015","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Thận - Đề HSG Tỉnh","q":"Tốc độ lọc cầu thận ($GFR$) là $120\\text{ ml/phút}$, nồng độ chất X trong huyết tương là $0.2\\text{ mg/ml}$, trong nước tiểu là $30\\text{ mg/ml}$ và lưu lượng nước tiểu là $1\\text{ ml/phút}$. Nhận định nào đúng?","opts":["Chất X được tái hấp thu một phần.","Chất X được tái hấp thu hoàn toàn.","Chất X được bài tiết thêm ở ống thận với tốc độ $6\\text{ mg/phút}$.","Chất X giống Inulin."],"ans":2,"exp":"Lượng lọc $= 120 \\times 0.2 = 24\\text{ mg/phút}$. Lượng thải $= 30 \\times 1 = 30\\text{ mg/phút} \\Rightarrow$ Bài tiết thêm $30 - 24 = 6\\text{ mg/phút}$."},{"id":"MCQ-PH-016","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Động học Quần thể Sinh thái - Đề HSG Tỉnh","q":"Quần thể cá tăng trưởng theo mô hình Logistic với $K = 2000$ cá thể và $r = 0.4\\text{ /năm}$. Để thu hoạch sản lượng cá bền vững tối đa hằng năm (MSY), cần duy trì kích thước quần thể ở mức nào và sản lượng khai thác tối đa mỗi năm là bao nhiêu?","opts":["$N = 1000$; khai thác $400$/năm.","$N = 2000$; khai thác $800$/năm.","$N = 500$; khai thác $200$/năm.","$N = 1000$; khai thác $200$/năm."],"ans":3,"exp":"Duy trì tại $N = K/2 = 1000$; tốc độ tăng trưởng cực đại $\\frac{rK}{4} = \\frac{0.4 \\times 2000}{4} = 200$ cá thể/năm."},{"id":"MCQ-PH-017","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Độc tố Thần kinh - Đề HSG Tỉnh","q":"Nếu ngâm sợi trục thần kinh mực ống vào dung dịch có bổ sung chất Tetraethylammonium (TEA - chất phong bế đặc hiệu kênh $K^+$ cổng điện thế), hình dạng đồ thị Điện thế hoạt động khi kích thích sợi trục sẽ biến đổi như thế nào?","opts":["Biên độ đỉnh điện thế hoạt động giảm đi một nửa.","Điện thế nghỉ trở nên âm hơn ($-90\\text{ mV}$).","Pha khử cực diễn ra bình thường nhưng pha tái phân cực bị kéo dài rất lâu và mất giai đoạn quá phân cực (hyperpolarization).","Không xuất hiện pha khử cực."],"ans":2,"exp":"Kênh $K^+$ cổng điện thế bị TEA khóa nên $K^+$ không thoát nhanh ra ngoài được $\\rightarrow$ pha tái phân cực kéo dài và mất pha quá phân cực."},{"id":"MCQ-PH-018","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Nội tiết Tuyến giáp - Đề HSG Tỉnh","q":"Một bệnh nhân có kết quả xét nghiệm máu: Nồng độ $T_3, T_4$ tự do rất cao, nhưng nồng độ $TSH$ và $TRH$ lại giảm xuống mức cực thấp. Khám lâm sàng thấy bệnh nhân bị bướu cổ to, nhịp tim nhanh, sụt cân và lồi mắt. Nguyên nhân gây bệnh phù hợp nhất là:","opts":["Khối u ở vùng dưới đồi tiết quá nhiều TRH.","Mắc bệnh Basedow (Graves): Cơ thể sinh kháng thể tự miễn TSI gắn vào thụ thể TSH trên tuyến giáp, kích thích tuyến giáp tiết quá mức $T_3, T_4$ và gây ức chế ngược âm tính lên vùng dưới đồi - tuyến yên.","Suy thùy trước tuyến yên.","Chế độ ăn thiếu Iodine trầm trọng."],"ans":1,"exp":"Kháng thể TSI bắt chước TSH kích thích tuyến giáp liên tục tạo nhiều $T_3/T_4$; lượng $T_3/T_4$ cao ức chế ngược làm giảm $TRH$ và $TSH$."},{"id":"MCQ-PH-019","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Hô hấp Phổi - Đề HSG Tỉnh","q":"Một người có tần số hô hấp $f = 15\\text{ nhịp/phút}$, thể tích khí lưu thông mỗi nhịp thở $V_T = 500\\text{ ml}$ và thể tích khoảng chết giải phẫu $V_D = 150\\text{ ml}$. Nếu người này chuyển sang thở nông và nhanh với $f = 30\\text{ nhịp/phút}$ và $V_T = 250\\text{ ml}$, thông khí phế nang thực tế ($V_A$) trong 1 phút sẽ thay đổi như thế nào?","opts":["Tăng từ $3000\\text{ ml/phút}$ lên $5250\\text{ ml/phút}$.","Giảm mạnh từ $5250\\text{ ml/phút}$ xuống chỉ còn $3000\\text{ ml/phút}$.","Không đổi (vẫn bằng $7500\\text{ ml/phút}$).","Bằng $0\\text{ ml/phút}$."],"ans":1,"exp":"$V_{A1} = 15 \\times (500 - 150) = 5250\\text{ ml/phút}$; $V_{A2} = 30 \\times (250 - 150) = 3000\\text{ ml/phút}$."},{"id":"MCQ-PH-020","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hệ RAAS & Vỏ thượng thận - Đề HSG Tỉnh","q":"Một bệnh nhân bị khối u ở lớp cầu của vỏ tuyến thượng thận dẫn đến tăng tiết quá mức hormone Aldosterone nguyên phát (Hội chứng Conn). Các chỉ số sinh lý máu của bệnh nhân này sẽ thay đổi như thế nào?","opts":["Huyết áp tăng cao, $[Na^+]$ máu tăng, $[K^+]$ máu giảm (hạ Kali máu) và nồng độ Renin huyết tương giảm thấp.","Đường huyết giảm mạnh và nhiễm toan máu.","Huyết áp giảm thấp, $[Na^+]$ máu giảm, $[K^+]$ máu tăng cao và Renin tăng cao.","Cả Aldosterone và Renin đều tăng vọt."],"ans":0,"exp":"Aldosterone kích thích ống lượn xa và ống góp tái hấp thu $Na^+$ (kéo theo nước $\\rightarrow$ tăng thể tích máu $\\rightarrow$ tăng huyết áp) và bài tiết $K^+$ vào nước tiểu ($\\rightarrow$ hạ $K^+$ máu). Do huyết áp cao nên bộ máy cận cầu thận bị ức chế ngược làm nồng độ Renin giảm thấp."},{"id":"MCQ-PH-021","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chỉ số Đa dạng Sinh thái Simpson - Đề HSG Tỉnh","q":"Khảo sát hai quần xã thực vật (Quần xã I và Quần xã II) đều có 4 loài ($A, B, C, D$) và cùng có tổng số 100 cá thể:<br>• Quần xã I: $25A : 25B : 25C : 25D$.<br>• Quần xã II: $85A : 5B : 5C : 5D$.<br>Tính chỉ số đa dạng Simpson $D = 1 - \\sum p_i^2$ của Quần xã I và Quần xã II:","opts":["$D_I = 0.25$ và $D_{II} = 0.73$.","$D_I = 0.75$ và $D_{II} = 0.27$.","$D_I = 1.00$ và $D_{II} = 0.50$.","$D_I = 0.75$ và $D_{II} = 0.75$."],"ans":1,"exp":"• Ở Quần xã I: $p_A = p_B = p_C = p_D = 0.25 \\Rightarrow D_I = 1 - 4 \\times (0.25)^2 = 1 - 0.25 = 0.75$.<br>• Ở Quần xã II: $p_A = 0.85, p_B = p_C = p_D = 0.05 \\Rightarrow D_{II} = 1 - [0.85^2 + 3 \\times (0.05)^2] = 1 - (0.7225 + 0.0075) = 1 - 0.73 = 0.27$. Vậy Quần xã I có độ đồng đều và độ đa dạng cao hơn nhiều so với Quần xã II."},{"id":"MCQ-PH-022","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Miễn dịch học & HIV - Đề HSG Tỉnh","q":"Tại sao khi virus HIV tấn công và phá hủy đặc hiệu tế bào Lympho T hỗ trợ ($T_H$ hay $CD4^+$) thì cả đáp ứng miễn dịch tế bào lẫn đáp ứng miễn dịch dịch thể của người bệnh đều bị suy sụp nghiêm trọng?","opts":["Vì tế bào $T_H$ tiết ra các Cytokine (như Interleukin-2) cần thiết để hoạt hóa cả tế bào Lympho B (sản xuất kháng thể - miễn dịch dịch thể) lẫn tế bào Lympho T độc ($T_C / CD8^+$ - miễn dịch tế bào).","Vì tế bào $T_H$ là tế bào trực tiếp tiết ra kháng thể IgG và IgM.","Vì HIV phá hủy toàn bộ hồng cầu và tiểu cầu.","Vì tế bào $T_H$ là đại thực bào duy nhất trong máu."],"ans":0,"exp":"Tế bào $T_H$ ($CD4^+$) đóng vai trò trung tâm điều phối miễn dịch: tiết Cytokine kích thích tế bào B biệt hóa thành tương bào tạo kháng thể (miễn dịch dịch thể) và kích thích tế bào $T_C$ ($CD8^+$) tiêu diệt tế bào nhiễm (miễn dịch tế bào)."},{"id":"MCQ-PH-023","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Trao đổi nước ở Thực vật","q":"Con đường vận chuyển nước và ion khoáng từ lông hút đi qua các khoảng trống giữa các bó sợi xenlulôzơ của thành tế bào rồi tới nội bì (dừng lại ở đai Caspary) được gọi là:","opts":["Con đường gian bào (Apoplast).","Con đường vận chuyển chủ động qua không bào.","Con đường tế bào chất (Symplast).","Con đường mạch rây (Phloem)."],"ans":0,"exp":"Con đường gian bào di chuyển nhanh qua thành tế bào và gian bào, khi đến tế bào nội bì có đai Caspary không thấm nước buộc phải chuyển sang con đường tế bào chất để kiểm soát chọn lọc."},{"id":"MCQ-PH-024","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Trao đổi nước ở Thực vật","q":"Cấu trúc đai Caspary nằm ở thành tế bào nội bì của rễ cây có chức năng sinh lý quan trọng nào?","opts":["Ngăn cản hoàn toàn oxy thấm vào mô mềm vỏ rễ.","Chặn dòng nước đi theo con đường gian bào, buộc nước và các ion khoáng đi qua màng sinh chất tế bào nội bì để kiểm soát lượng khoáng đi vào mạch gỗ.","Tăng tốc độ khuếch tán tự do mọi ion độc hại vào trung trụ.","Dự trữ tinh bột làm nguồn năng lượng cho lá quang hợp."],"ans":1,"exp":"Đai Caspary thấm chất suberin không thấm nước giúp kiểm soát sự hấp thụ chọn lọc nước và ion khoáng trước khi đẩy vào mạch dẫn (xylem)."},{"id":"MCQ-PH-025","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thoát hơi nước ở Lá","q":"Phần lớn lượng nước hấp thụ ở rễ ($>98\\%$) thoát ra khỏi lá qua con đường nào và có vai trò chủ yếu gì?","opts":["Không thoát hơi nước mà tích lũy hoàn toàn thành dịch không bào.","Thoát hơi nước chủ yếu qua tầng cutin dày; giúp tăng nhiệt độ mô lá.","Thoát hơi nước qua rễ; giúp thải độc kim loại nặng.","Thoát hơi nước qua khí khổng; giúp tạo lực hút đầu trên, hạ nhiệt độ lá và mở đường cho $CO_2$ khuếch tán vào lá để quang hợp."],"ans":3,"exp":"Thoát hơi nước qua khí khổng điều tiết được và tạo động lực hút dòng mạch gỗ từ rễ lên lá, làm mát lá và cho phép trao đổi khí $CO_2$ phục vụ quang hợp."},{"id":"MCQ-PH-026","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dinh dưỡng Khoáng ở Thực vật","q":"Nguyên tố khoáng thiết yếu nào là thành phần cấu tạo bắt buộc ở trung tâm vòng porphyrin của phân tử diệp lục (Chlorophyll), khi thiếu lá bị vàng gân lá (vàng úa ở lá già trước)?","opts":["Canxi ($Ca^{2+}$).","Molybden ($Mo$).","Magiê ($Mg^{2+}$).","Lưu huỳnh ($SO_4^{2-}$)."],"ans":2,"exp":"Mỗi phân tử diệp lục chứa $1$ nguyên tử $Mg$ ở tâm vòng porphyrin; vì $Mg$ linh động trong mạch rây nên khi thiếu cây huy động từ lá già sang lá non làm lá già vàng trước."},{"id":"MCQ-PH-027","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quang hợp Thực vật","q":"Phản ứng quang phân ly nước ($2 H_2O \\rightarrow 4 H^+ + 4 e^- + O_2$) diễn ra ở vị trí nào trong lục lạp?","opts":["Chất nền lục lạp (Stroma) trong chu trình Calvin.","Xoang tilacoit (mặt trong màng tilacoit, liên kết với hệ quang hóa PS II).","Tế bào chất bên ngoài lục lạp.","Màng ngoài của lục lạp."],"ans":1,"exp":"Pha sáng quang hợp giải phóng $O_2$ từ quang phân ly nước xảy ra tại phức hệ OEC ở mặt xoang màng tilacoit (thuộc PS II)."},{"id":"MCQ-PH-028","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quang hợp Thực vật","q":"Sản phẩm đầu tiên ổn định chứa cacbon được cố định từ $CO_2$ trong pha tối của nhóm thực vật $C_3$ (lúa, đậu, khoai) là hợp chất nào?","opts":["Fructôzơ-1,6-bisphotphat ($6$ cacbon).","Axit 3-photphoglixeric (3-PGA hay APG, hợp chất $3$ cacbon).","Axit oxaloaxetic (OAA, hợp chất $4$ cacbon).","Axit malic ($4$ cacbon) tích lũy trong không bào."],"ans":1,"exp":"Enzyme RuBisCO xúc tác $CO_2$ kết hợp với RuBP ($5C$) tạo chất $6C$ không bền tách ngay thành $2$ phân tử 3-PGA ($3C$)."},{"id":"MCQ-PH-029","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quang hợp C3, C4 và CAM","q":"Điểm khác biệt đặc trưng giúp thực vật CAM (dứa, xương rồng, thanh long) thích nghi với môi trường hoang mạc khô hạn là:","opts":["Không có pha tối mà chỉ dùng năng lượng nhiệt để tổng hợp đường.","Không có khí khổng trên lá mà hấp thụ $CO_2$ qua rễ chùm.","Khí khổng đóng vào ban ngày để hạn chế mất nước và mở vào ban đêm để cố định $CO_2$ dưới dạng axit malic dự trữ trong không bào.","Chỉ quang hợp ở dưới đáy biển sâu không cần ánh sáng."],"ans":2,"exp":"Thực vật CAM tách biệt pha tối thành $2$ thời điểm: cố định $CO_2$ ban đêm (tạo OAA $\\rightarrow$ malat tích trong không bào) và chu trình Calvin khử $CO_2$ ban ngày khi khí khổng đóng."},{"id":"MCQ-PH-030","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp ở Thực vật","q":"Trong kỹ thuật bảo quản nông sản (hạt thóc, ngô, rau quả tươi), biện pháp phơi khô hạt xuống độ ẩm an toàn ($10-13\\%$) và giữ kho thoáng mát nhằm mục đích sinh lý gì?","opts":["Đưa cường độ hô hấp tế bào về mức tối thiểu để giảm tiêu hao chất hữu cơ dự trữ mà vẫn giữ phôi hạt sống.","Tiêu diệt toàn bộ tế bào phôi bên trong hạt để hạt không nảy mầm.","Kích thích tổng hợp Etilen làm quả nhanh chín.","Thúc đẩy quá trình lên men rượu tích tụ etylic làm tăng hương thơm."],"ans":0,"exp":"Giảm độ ẩm tự do và hạ nhiệt độ thích hợp làm giảm hoạt tính enzyme hô hấp, hạn chế mất khối lượng khô và sinh nhiệt gây thối hỏng."},{"id":"MCQ-PH-031","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cảm ứng ở Thực vật","q":"Hiện tượng thân cây non uốn cong mọc hướng về phía nguồn sáng chiếu từ một phía (hướng sáng dương) xảy ra do cơ chế nào?","opts":["Auxin tập trung nhiều hơn ở phía tối của thân, kích thích các tế bào phía tối dãn dài nhanh hơn phía được chiếu sáng.","Gibberellin tiêu hủy hết tế bào phía được chiếu sáng.","Các tế bào phía sáng tự động co ngắn mất nước đột ngột.","Cytokinin tập trung dày đặc ở phía tối ức chế phân chia."],"ans":0,"exp":"Ánh sáng làm auxin di chuyển sang mặt khuất sáng của chồi ngọn; nồng độ auxin cao hơn (trong ngưỡng thích hợp ở thân) kích thích sự dãn dài tế bào làm thân cong về phía ánh sáng."},{"id":"MCQ-PH-032","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hormone Thực vật","q":"Hormone thực vật nào tồn tại ở dạng khí, có tác dụng thúc đẩy nhanh quá trình chín của quả, kích thích rụng lá và già hóa?","opts":["Gibberellin ($GA_3$).","Auxin ($IAA$).","Etilen ($C_2H_4$).","Cytokinin."],"ans":2,"exp":"Etilen là phytohormone dạng khí kích thích tổng hợp các enzyme thủy phân vách tế bào, biến đổi tinh bột thành đường và phân giải diệp lục khi quả chín."},{"id":"MCQ-PH-033","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tiêu hóa ở Động vật","q":"Ở động vật nhai lại (trâu, bò, cừu), ngăn dạ dày nào tiết axit $HCl$ và enzyme pepsin tiêu hóa protein thức ăn tương tự dạ dày người và thú ăn thịt (gọi là dạ dày chính thức)?","opts":["Dạ tổ ong.","Dạ lá sách.","Dạ múi khế.","Dạ cỏ."],"ans":2,"exp":"Trong $4$ ngăn dạ dày của trâu bò (dạ cỏ $\\rightarrow$ dạ tổ ong $\\rightarrow$ dạ lá sách $\\rightarrow$ dạ múi khế), chỉ có dạ múi khế tiết $HCl$ và pepsin tiêu hóa vi sinh vật và protein."},{"id":"MCQ-PH-034","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp ở Động vật","q":"Cơ chế thông khí ở hệ hô hấp bằng phổi của chim có hiệu quả trao đổi khí vượt trội so với phổi thú nhờ đặc điểm cấu tạo nào?","opts":["Phổi chim gồm hệ thống ống khí thông với các túi khí trước và sau giúp dòng không khí giàu $O_2$ đi qua phổi theo MỘT CHIỀU liên tục cả khi hít vào lẫn thở ra (không có khí cặn đọng ở phế nang).","Phổi chim chứa hàng tỷ phế nang tĩnh lớn gấp $10$ lần thú.","Hồng cầu chim không cần hemoglobin mà tự hòa tan $O_2$.","Chim thở trực tiếp qua da ướt và không có phổi."],"ans":0,"exp":"Hệ thống túi khí giúp không khí đi qua hệ thống ống khí phổi theo dòng chảy một chiều khép kín, không bị pha trộn với khí giàu $CO_2$ cũ."},{"id":"MCQ-PH-035","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp ở Cá xương","q":"Nhờ dòng nước chảy qua phiến mang ngược chiều với dòng máu chảy trong mao mạch mang (cơ chế dòng chảy song song ngược chiều), cá xương đạt được ưu thế trao đổi khí nào?","opts":["Cho phép cá lên cạn thở không khí khô suốt mùa hè.","Làm tim cá chỉ cần $1$ ngăn duy nhất vẫn đủ áp lực.","Giúp máu bão hòa $50\\%$ $O_2$ và dừng lại ngay giữa phiến mang.","Duy trì hiệu số phân áp chênh lệch $O_2$ dọc toàn bộ chiều dài mao mạch mang, thu hồi được trên $80\\%$ lượng $O_2$ hòa tan trong nước."],"ans":3,"exp":"Dòng chảy ngược chiều giữ cho áp suất riêng phần $O_2$ trong nước luôn cao hơn trong máu suốt đường tiếp xúc, tối đa hóa hiệu suất khuếch tán."},{"id":"MCQ-PH-036","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tuần hoàn Máu","q":"Trong hệ tuần hoàn kín của người, vận tốc máu chảy CHẬM NHẤT ở loại mạch máu nào và ý nghĩa sinh lý là gì?","opts":["Tĩnh mạch chủ trên; giúp tránh trào ngược máu về tâm thất.","Động mạch chủ; giúp tim giảm áp lực co bóp.","Mao mạch; do tổng tiết diện ngang lớn nhất, giúp kéo dài thời gian tiếp xúc để trao đổi chất giữa máu và dịch mô hiệu quả.","Tiểu động mạch; giúp ngăn ngừa hiện tượng đông máu."],"ans":2,"exp":"Vận tốc máu tỉ lệ nghịch với tổng tiết diện mạch ($v = Q/A$). Tổng tiết diện toàn bộ hệ mao mạch lớn nhất nên máu chảy chậm nhất ($\\approx 0.5\\text{ mm/s}$), thuận lợi trao đổi khí và chất dinh dưỡng."},{"id":"MCQ-PH-037","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hệ Tuần hoàn Động vật","q":"Trong các nhóm động vật có xương sống sau đây, nhóm nào có hệ tuần hoàn KÉP nhưng tim vẫn chỉ có $3$ ngăn ($2$ tâm nhĩ, $1$ tâm thất) dẫn đến máu đi nuôi cơ thể là máu pha?","opts":["Cá sụn và cá xương.","Chim và Động vật có vú.","Lưỡng cư (ếch nhái) và hầu hết Bò sát (trừ cá sấu).","Giun đốt và Chân khớp."],"ans":2,"exp":"Lưỡng cư và phần lớn bò sát có hệ tuần hoàn kép với $1$ tâm thất chung nhận cả máu giàu $O_2$ từ phổi và máu nghèo $O_2$ từ cơ thể (bò sát có vách ngăn hụt nên đỡ pha trộn hơn lưỡng cư)."},{"id":"MCQ-PH-038","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cân bằng Nội môi & Bài tiết","q":"Khi cơ thể bị mất nước nhiều (như ra mồ hôi nhiều khi chạy bộ), áp suất thẩm thấu của máu tăng lên sẽ kích thích vùng dưới đồi và thùy sau tuyến yên tăng tiết hormone nào để thận tăng tái hấp thu nước?","opts":["Hormone Insulin.","Hormone Thyroxine ($T_4$).","Hormone Glucagon.","Hormone chống bài niệu $ADH$ (Vasopressin)."],"ans":3,"exp":"$ADH$ gắn vào thụ thể trên tế bào ống góp và ống lượn xa của nephron, kích thích gắn các kênh nước aquaporin-2 lên màng để tăng tái hấp thu nước vào máu."},{"id":"MCQ-PH-039","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dẫn truyền Xung thần kinh","q":"Trên sợi trục thần kinh có bao myelin (vỏ bọc chất béo cách điện), xung thần kinh dẫn truyền nhanh hơn rất nhiều so với sợi không có myelin vì:","opts":["Xung thần kinh biến thành chất dẫn truyền khuếch tán thẳng qua tế bào Schwann.","Bao myelin làm mở toàn bộ kênh $K^+$ liên tục dọc sợi trục.","Đường kính sợi có myelin nhỏ hơn $100$ lần nên không tốn ATP.","Xung điện nhảy cóc từ eo Ranvier này sang eo Ranvier kế tiếp."],"ans":3,"exp":"Bao myelin cách điện chỉ để hở các eo Ranvier giàu kênh $Na^+$/$K^+$ điện thế, do đó điện thế hoạt động tái sinh theo kiểu nhảy cóc vừa nhanh vừa tiết kiệm năng lượng cho bơm $Na^+/K^+$."},{"id":"MCQ-PH-040","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Xinap Thần kinh","q":"Vai trò trực tiếp của ion $Ca^{2+}$ khi điện thế hoạt động truyền tới chùy xinap (màng trước xinap) là gì?","opts":["Phân hủy phân tử ATP thành glucose tự do.","Bám trực tiếp vào cơ vân làm đóng chặt màng sau xinap.","Đi vào chùy xinap kích thích các bóng chứa chất dẫn truyền thần kinh dung hợp với màng trước xinap để xuất bào chất trung gian hóa học vào khe xinap.","Ức chế hoàn toàn sự giải phóng Acetylcholine."],"ans":2,"exp":"Khử cực chùy xinap mở kênh $Ca^{2+}$ cổng điện thế; $Ca^{2+}$ tràn vào kích hoạt phức hợp protein SNARE đẩy túi xinap hòa màng (exocytosis)."},{"id":"MCQ-PH-041","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh thái học Cá thể","q":"Khoảng giá trị xác định của một nhân tố sinh thái (như nhiệt độ từ $5.6^\\circ\\text{C}$ đến $42^\\circ\\text{C}$ đối với cá rô phi Việt Nam) mà trong khoảng đó sinh vật có thể tồn tại và phát triển ổn định được gọi là:","opts":["Giới hạn sinh thái.","Chuỗi thức ăn cân bằng.","Khu sinh học (Biome).","Ổ sinh thái đầy đủ."],"ans":0,"exp":"Giới hạn sinh thái là khoảng giá trị cực tiểu đến cực đại (điểm gây chết dưới $\\rightarrow$ điểm gây chết trên) của một nhân tố sinh thái mà sinh vật có thể chịu đựng."},{"id":"MCQ-PH-042","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quan hệ Sinh thái Quần xã","q":"Mối quan hệ giữa chim sáo đậu trên lưng trâu rừng vừa ăn ve bét giúp trâu sạch ký sinh trùng vừa có nguồn thức ăn (cả hai bên đều có lợi nhưng không bắt buộc phải sống chung) là ví dụ của:","opts":["Quan hệ cộng sinh bắt buộc.","Quan hệ hội sinh.","Quan hệ hợp tác.","Quan hệ ức chế - cảm nhiễm."],"ans":2,"exp":"Hợp tác ($+/+$) mang lại lợi ích cho cả hai loài nhưng không nhất thiết phụ thuộc sinh tồn bắt buộc như cộng sinh (địa y, vi khuẩn nốt sần)."},{"id":"MCQ-PH-043","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quan hệ Sinh thái Quần xã","q":"Khi tảo giáp nở hoa gây 'thủy triều đỏ' đã tiết ra độc tố vào nước làm chết hàng loạt cá, tôm xung quanh trong khi bản thân tảo không sử dụng các loài cá đó làm thức ăn. Đây là kiểu quan hệ:","opts":["Ức chế - cảm nhiễm ($0/-$).","Hội sinh ($+/0$).","Cộng sinh ($+/+$).","Sinh vật ăn sinh vật ($+/-$)."],"ans":0,"exp":"Ức chế - cảm nhiễm là quan hệ trong đó một loài trong quá trình sống vô tình (hoặc do tiết chất trao đổi) gây hại cho loài khác mà không thu lợi ích dinh dưỡng trực tiếp."},{"id":"MCQ-PH-044","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chuỗi & Lưới thức ăn","q":"Trong một hệ sinh thái đồng cỏ: Cỏ $\\rightarrow$ Châu chấu $\\rightarrow$ Ếch đồng $\\rightarrow$ Rắn hổ mang $\\rightarrow$ Đại bàng. Trong chuỗi thức ăn này, Ếch đồng thuộc bậc dinh dưỡng cấp mấy và là sinh vật tiêu thụ bậc mấy?","opts":["Bậc dinh dưỡng cấp $2$; sinh vật tiêu thụ bậc $1$.","Bậc dinh dưỡng cấp $3$; sinh vật sản xuất.","Bậc dinh dưỡng cấp $4$; sinh vật tiêu thụ bậc $3$.","Bậc dinh dưỡng cấp $3$; sinh vật tiêu thụ bậc $2$."],"ans":3,"exp":"Cỏ (SVSX = Bậc 1) $\\rightarrow$ Châu chấu (SVTT bậc 1 = Bậc 2) $\\rightarrow$ Ếch (SVTT bậc 2 = Bậc dinh dưỡng cấp 3)."},{"id":"MCQ-PH-045","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Diễn thế Sinh thái","q":"Quá trình biến đổi tuần tự của quần xã sinh vật khởi đầu từ một môi trường trống trơn chưa hề có sinh vật sinh sống (như đảo núi lửa mới nhô lên hoặc bãi cát mới bồi tụ) cho tới khi hình thành quần xã đỉnh cực gọi là:","opts":["Diễn thế thứ sinh.","Hiện tượng phì dưỡng hồ nước.","Diễn thế nguyên sinh.","Biến động số lượng theo mùa."],"ans":2,"exp":"Diễn thế nguyên sinh bắt đầu từ sinh cảnh trống hoàn toàn chưa có đất hay mầm mống sinh vật; diễn thế thứ sinh bắt đầu trên môi trường đã từng có quần xã sinh vật nhưng bị tàn phá."},{"id":"MCQ-PH-046","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chu trình Sinh địa hóa","q":"Trong chu trình Nitơ tự nhiên, quá trình chuyển hóa nitrat ($NO_3^-$) thành nitơ phân tử ($N_2$) bay trả lại khí quyển do các vi khuẩn phản nitrat hóa thực hiện mạnh trong điều kiện nào?","opts":["Ánh sáng mặt trời chiếu trực tiếp lên bề mặt lá cây.","Đất bị ngập úng lâu ngày, yếm khí (thiếu $O_2$).","Đất tơi xốp giàu oxy thoáng khí tốt.","Nước biển có độ pH trên $10$."],"ans":1,"exp":"Vi khuẩn phản nitrat hóa sử dụng $NO_3^-$ làm chất nhận điện tử cuối cùng trong hô hấp kị khí ở đất bí khí, gây thất thoát đạm khỏi đất trồng."},{"id":"MCQ-PH-047","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chu trình Carbon","q":"Nguyên nhân trực tiếp dẫn đến hàm lượng khí $CO_2$ trong khí quyển tăng nhanh gây hiệu ứng nhà kính và biến đổi khí hậu toàn cầu hiện nay là:","opts":["Hô hấp quá mức của tảo biển làm đóng băng đại dương.","Đốt cháy quá mức nhiên liệu hóa thạch (than đá, dầu mỏ, khí đốt) kết hợp với chặt phá rừng làm giảm hấp thụ quang hợp.","Lượng nitơ tự do ($N_2$) biến hết thành $CO_2$.","Tầng ozon hấp thụ hết tia sáng đỏ dùng cho quang hợp."],"ans":1,"exp":"Giải phóng cacbon hóa thạch lưu giữ hàng trăm triệu năm kết hợp thu hẹp thảm thực vật làm mất cân bằng chu trình cacbon."},{"id":"MCQ-PH-048","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tháp Sinh thái","q":"Dạng tháp sinh thái nào LUÔN LUÔN có đáy rộng và đỉnh hẹp chuẩn mực ở MỌI hệ sinh thái trên cạn cũng như dưới nước (không bao giờ có tháp lộn ngược)?","opts":["Tháp độ tuổi quần thể.","Tháp sinh khối.","Tháp số lượng.","Tháp năng lượng."],"ans":3,"exp":"Theo định luật nhiệt động lực học thứ II và hiệu suất sinh thái ($\\sim 10\\%$ truyền lên bậc kế tiếp), dòng năng lượng qua mỗi bậc dinh dưỡng luôn suy giảm mạnh ($\\ge 80-90\\%$ thất thoát qua hô hấp và chất thải) nên tháp năng lượng không thể lộn ngược."},{"id":"MCQ-PH-049","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hệ sinh thái & Sinh quyển","q":"Khu sinh học (Biome) trên cạn có độ đa dạng loài và năng suất sinh học sơ cấp trên một đơn vị diện tích cao nhất hành tinh là:","opts":["Sa mạc và bán hoang mạc.","Đồng rêu hàn đới (Tundra).","Rừng lá kim phương Bắc (Taiga).","Rừng mưa nhiệt đới."],"ans":3,"exp":"Nhiệt độ ấm áp, bức xạ mặt trời dồi dào và lượng mưa cao quanh năm giúp rừng mưa nhiệt đới dẫn đầu về sức sản xuất và độ đa dạng sinh học."},{"id":"MCQ-PH-050","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tiêu hóa & Hấp thụ ở Người","q":"Đơn vị hấp thụ chính thức các chất dinh dưỡng đã tiêu hóa (axit amin, đường đơn, axit béo vào mạch bạch huyết/máu) diễn ra mạnh nhất ở đoạn nào của ống tiêu hóa người?","opts":["Thực quản.","Ruột già (kết tràng).","Dạ dày.","Ruột non (nhờ hệ thống nếp gấp, lông ruột và vi nhung mao tạo diện tích bề mặt cực lớn)."],"ans":3,"exp":"Cấu trúc 3 cấp (nếp vòng $\\rightarrow$ nhung mao $\\rightarrow$ vi nhung mao) làm tăng diện tích tiếp xúc niêm mạc ruột non lên hàng trăm $m^2$."},{"id":"MCQ-PH-051","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh lý Máu & Miễn dịch","q":"Loại bạch cầu nào trong hệ miễn dịch đóng vai trò tiết ra kháng thể (Immunoglobulin - Ig) đặc hiệu để trung hòa độc tố vi khuẩn và virus trong miễn dịch dịch thể?","opts":["Tế bào Hồng cầu trưởng thành.","Tiểu cầu.","Tế bào tương bào (biệt hóa từ tế bào Lympho B).","Tế bào Lympho T gây độc ($T_C$ / $CD8^+$)."],"ans":2,"exp":"Khi nhận diện kháng nguyên và được trợ giúp từ $T_H$, tế bào Lympho B tăng sinh và biệt hóa thành tương bào (Plasma cell) tiết ra lượng lớn kháng thể hòa tan."},{"id":"MCQ-PH-052","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh lý Thần kinh & Giác quan","q":"Trên một cung phản xạ điển hình ở động vật có hệ thần kinh dạng ống, trật tự truyền tín hiệu chính xác qua $5$ khâu là:","opts":["Trung ương thần kinh $\\rightarrow$ Nơron hướng tâm $\\rightarrow$ Thụ thể $\\rightarrow$ Cơ quan trả lời $\\rightarrow$ Nơron ly tâm.","Thụ thể tiếp nhận kích thích $\\rightarrow$ Nơron hướng tâm (cảm giác) $\\rightarrow$ Trung ương thần kinh (tủy sống/não) $\\rightarrow$ Nơron ly tâm (vận động) $\\rightarrow$ Cơ quan trả lời.","Cơ quan trả lời $\\rightarrow$ Nơron cảm giác $\\rightarrow$ Thụ thể $\\rightarrow$ Cơ quan đáp ứng.","Nơron vận động $\\rightarrow$ Thụ thể $\\rightarrow$ Máu $\\rightarrow$ Trung ương thần kinh."],"ans":1,"exp":"Cung phản xạ luôn đi theo đúng một chiều cố định từ bộ phận tiếp nhận kích thích về trung ương phân tích xử lý rồi truyền lệnh ra cơ quan thực hiện."},{"id":"MCQ-PH-053","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vận chuyển các chất trong Cây","q":"Dòng mạch rây (Phloem) vận chuyển các sản phẩm quang hợp (chủ yếu là đường saccarôzơ) từ nguồn (lá) tới nơi chứa (quả, rễ, củ) hoạt động theo cơ chế nào?","opts":["Chỉ vận chuyển một chiều duy nhất từ rễ lên chồi ngọn nhờ lực hút thoát hơi nước.","Nhờ sự co bóp nhịp nhàng như tim của các tế bào vỏ cây.","Chỉ xảy ra vào ban đêm khi nhiệt độ dưới $0^\\circ\\text{C}$.","Chênh lệch áp suất thẩm thấu (áp suất thủy tĩnh dòng áp lực Munch) tạo bởi sự nạp chủ động đường ở tế bào kèm nguồn và rút đường ở nơi chứa."],"ans":3,"exp":"Tại nguồn, đường saccarôzơ được bơm vào ống rây kéo nước từ mạch gỗ vào làm tăng áp suất đẩy dịch xuống nơi chứa có áp suất thấp."},{"id":"MCQ-PH-054","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp & Tuần hoàn ở Người","q":"Giá trị huyết áp tâm thu / huyết áp tâm trương bình thường của một người trưởng thành khỏe mạnh khi nghỉ ngơi đo ở động mạch cánh tay xấp xỉ:","opts":["$220 / 140\\text{ mmHg}$.","$80 / 120\\text{ mmHg}$.","$120 / 80\\text{ mmHg}$.","$40 / 20\\text{ mmHg}$."],"ans":2,"exp":"Huyết áp tâm thu (tối đa lúc thất trái tống máu) $\\approx 110-120\\text{ mmHg}$ và huyết áp tâm trương (lúc tim dãn) $\\approx 70-80\\text{ mmHg}$."},{"id":"MCQ-PH-055","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quang hợp Thực vật C3 - C4","q":"Thực vật $C_4$ (ngô, mía, cao lương) cho năng suất sinh học cao hơn hẳn thực vật $C_3$ trong điều kiện nhiệt độ cao, ánh sáng mạnh vì:","opts":["Thực vật $C_4$ có khả năng quang hợp xuyên đêm không cần diệp lục.","Có cơ chế cô đặc $CO_2$ trong tế bào bao bó mạch nhờ enzyme PEP-carboxylase có ái lực cao với $CO_2$ và không nhạy cảm với $O_2$, gần như triệt tiêu hô hấp sáng.","RuBisCO của thực vật $C_4$ hoạt động ngay trong màng nhân tế bào biểu bì.","Thực vật $C_4$ không cần nước và không có hệ thống mạch gỗ."],"ans":1,"exp":"Enzyme PEP-carboxylase ở mô giậu cố định $CO_2$ nồng độ thấp thành hợp chất $C_4$, sau đó giải phóng $CO_2$ tập trung tại tế bào bao bó mạch nơi có RuBisCO giúp ức chế hô hấp sáng."},{"id":"MCQ-PH-056","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh sản & Sinh trưởng Thực vật","q":"Xuân hóa (Vernalization) là hiện tượng sinh lý nào ở một số loài cây ôn đới và mùa đông?","opts":["Cây tự động rụng hết rễ vào mùa xuân.","Cây mất khả năng quang hợp vào ban ngày.","Cây hay hạt nảy mầm phải trải qua một giai đoạn nhiệt độ lạnh thích hợp thì mới có thể chuyển sang giai đoạn ra hoa kết quả.","Cây chỉ ra hoa khi bị thiêu đốt ở nhiệt độ trên $60^\\circ\\text{C}$."],"ans":2,"exp":"Ví dụ lúa mì mùa đông hoặc cải bắp cần kích thích lạnh kéo dài để cảm ứng mở khóa gen điều hòa ra hoa (như ức chế FLC)."},{"id":"MCQ-PH-057","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần xã & Loài ưu thế","q":"Trong một quần xã rừng thông ôn đới hoặc rừng đước ngập mặn ven biển, loài thông hay cây đước được gọi là loài ưu thế (Dominant species) vì:","opts":["Chúng chỉ xuất hiện ở đại Thái cổ rồi biến mất hoàn toàn.","Chúng là loài ký sinh nhỏ bé nhất trong quần xã.","Chúng có số lượng cá thể lớn, sinh khối cao và chi phối mạnh mẽ các điều kiện môi trường (ánh sáng, độ ẩm, đất) cũng như sự phân bố của các loài khác trong quần xã.","Chúng tuyệt đối không cần ánh sáng hay dinh dưỡng khoáng."],"ans":2,"exp":"Loài ưu thế quyết định diện mạo, tiểu khí hậu và cấu trúc dinh dưỡng nền tảng của quần xã nhờ sinh khối và số lượng áp đảo."},{"id":"MCQ-PH-058","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh thái Phục hồi & Ô nhiễm","q":"Hiện tượng phì dưỡng (Eutrophication) ở các ao hồ nước ngọt xảy ra khi dư thừa lượng lớn muối nitrat ($NO_3^-$) và photphat ($PO_4^{3-}$) từ phân bón, nước thải dẫn tới hệ quả nguy hiểm nào?","opts":["Nước hồ trở nên trong vắt hoàn toàn và tăng hàm lượng $O_2$ bão hòa.","Tảo phát triển bùng nổ rồi chết hàng loạt; vi khuẩn hiếu khí phân hủy xác tảo tiêu thụ cạn kiệt $O_2$ hòa tan làm cá và thủy sinh vật chết ngạt.","Cá trong hồ tăng kích thước gấp $10$ lần chỉ sau $1$ tuần.","Toàn bộ chu trình cacbon trong hồ dừng vĩnh viễn."],"ans":1,"exp":"Tảo nở hoa che khuất ánh sáng tầng sâu và khi phân hủy tạo nhu cầu oxy sinh hóa (BOD) cực lớn, gây thiếu oxy trầm trọng (vùng chết thủy sinh)."},{"id":"MCQ-PH-059","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hormone Động vật","q":"Khi cơ thể người gặp tình huống căng thẳng khẩn cấp (đối mặt nguy hiểm: 'chiến đấu hay bỏ chạy'), tủy tuyến thượng thận tăng tiết nhanh hormone nào làm tim đập nhanh, dãn phế quản và tăng phân giải glycogen thành glucose?","opts":["Hormone sinh trưởng $GH$.","Adrenalin (Epinephrine) và Noradrenalin.","Melatonin của tuyến tùng.","Prolactin."],"ans":1,"exp":"Adrenalin huy động phản ứng giao cảm cấp tính, tăng cung lượng tim, dồn máu về cơ xương và tăng đường huyết khẩn cấp."},{"id":"MCQ-PH-060","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hệ Thần kinh & Sinh học Tế bào","q":"Chất dẫn truyền thần kinh kích thích phổ biến nhất giải phóng tại synap thần kinh - cơ vân ở động vật có xương sống để gây co cơ là:","opts":["Axit gamma-aminobutyric ($GABA$).","Acetylcholine ($ACh$).","Hemoglobin.","Axit uric."],"ans":1,"exp":"Nơron vận động giải phóng Acetylcholine gắn vào thụ thể nicotinic trên màng sợi cơ vân gây khử cực mở kênh $Na^+$ khởi phát co cơ (trong khi $GABA$ là chất ức chế chính ở não)."},{"id":"MCQ-PH-061","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp Tế bào Thực vật & Động vật","q":"Khi tế bào rễ cây lúa bị ngập úng kéo dài không có $O_2$, rễ vẫn có thể tạo được một lượng ATP ít ỏi tạm thời qua quá trình nào và hậu quả gây chết rễ nếu kéo dài là gì?","opts":["Thực hiện chu trình Krebs thu được $38\\text{ ATP}$ không cần oxy.","Tăng cường vận chuyển chủ động hấp thụ nitrat cấp $10$ lần bình thường.","Lên men tạo etanol (hoặc axit lactic) chỉ thu $2\\text{ ATP}$/glucose; kéo dài gây ngộ độc cồn, axit hóa tế bào chất và cạn kiệt năng lượng.","Quang phân ly nước ngay trong lòng đất để thu $O_2$."],"ans":2,"exp":"Thiếu $O_2$ làm chuỗi chuyền điện tử ty thể đình trệ, tế bào chuyển sang lên men tái sinh $NAD^+$ cho đường phân với hiệu suất rất thấp ($2\\text{ ATP}$) và tích tụ độc tố lên men."},{"id":"MCQ-PH-062","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh lý Đông máu","q":"Trong quá trình đông máu bảo vệ cơ thể khi bị thương rách mạch máu, enzyme thrombin xúc tác biến đổi chất nào hòa tan trong huyết tương thành mạng lưới sợi không hòa tan bắt giữ các tế bào máu?","opts":["Chuyển Glucozo thành tinh bột.","Chuyển Hemoglobin thành Bilirubin.","Chuyển Fibrinogen (hòa tan) thành các sợi Fibrin (không tan).","Chuyển Urê thành axit amin."],"ans":2,"exp":"Dòng thác đông máu chuyển prothrombin thành thrombin; thrombin cắt fibrinogen hòa tan thành mạng tơ huyết fibrin giữ hồng cầu, tiểu cầu bịt vết thương."},{"id":"MCQ-PH-063","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cơ chế Mở đóng Khí khổng","q":"Khí khổng thực vật mở ra khi tế bào khí khổng (tế bào bảo vệ) có biểu hiện nào sau đây về trạng thái trương nước?","opts":["Hút nước mạnh (trương nước tăng), làm thành mỏng phía ngoài căng cong kéo theo thành dày phía trong tách nhau tạo khe hở khí khổng.","Mất nước co nguyên sinh hoàn toàn khiến hai tế bào ép sát vào nhau.","Mất toàn bộ lục lạp và ngừng vận chuyển $K^+$.","Tổng hợp lớp cutin bít kín toàn bộ lỗ khí."],"ans":0,"exp":"Cấu tạo thành vách không đều (mặt trong hướng khe dày, mặt ngoài mỏng) làm tế bào khí khổng uốn cong khi trương nước và khép lại khi mất nước."},{"id":"MCQ-PH-064","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cân bằng Nước & Sinh vật","q":"Loài cá xương sống ở biển (nước biển ưu trương hơn dịch cơ thể cá) phải đối mặt với nguy cơ sinh lý nào và thích nghi bằng cách nào?","opts":["Thải lượng lớn nước tiểu rất loãng như cá nước ngọt.","Nguy cơ mất nước qua mang và da; cá xương biển uống nước biển liên tục và chủ động thải muối thừa qua tế bào clorua ở mang, thải ít nước tiểu đẳng trương.","Nguy cơ trương nước vỡ tế bào nên không bao giờ uống nước.","Tăng tích tụ axit sunfuric trong mang."],"ans":1,"exp":"Do cơ thể nhược trương so với nước biển ($\\approx 1000\\text{ mOsm}$ vs $\\approx 300\\text{ mOsm}$), cá xương biển mất nước liên tục nên phải uống nước biển và bơm tích cực $Na^+, Cl^-$ ra ngoài qua mang."},{"id":"MCQ-PH-065","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tập tính Động vật","q":"Hiện tượng vịt con mới nở bám theo bất kỳ vật thể chuyển động nào đầu tiên mà nó nhìn thấy (ví dụ mẹ vịt hoặc nhà khoa học Konrad Lorenz) thuộc hình thức học tập nào?","opts":["Quen nhờn (Habituation).","Điều kiện hóa thao tác.","In vết (Imprinting).","Học khôn (Insight learning)."],"ans":2,"exp":"In vết xảy ra trong giai đoạn nhạy cảm rất sớm ngay sau khi sinh, tạo gắn kết bền vững giúp con non nhận diện bố mẹ hoặc đồng loại."},{"id":"MCQ-PH-066","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sinh thái Học Quần xã","q":"Trong một khu rừng có nhiều tầng tán (tầng vượt tán, tầng tán rừng, tầng dưới tán, tầng thảm tươi). Ý nghĩa sinh thái chủ yếu của sự phân tầng theo chiều thẳng đứng trong quần xã là gì?","opts":["Ngăn chặn quá trình quang hợp ở tất cả tầng cây dưới.","Giảm sự cạnh tranh giữa các loài, đồng thời tận dụng tối đa nguồn ánh sáng, không gian và thức ăn ở mọi mức cao độ.","Ép toàn bộ động vật xuống sống chung một mét vuông mặt đất.","Loại bỏ hoàn toàn lưới thức ăn."],"ans":1,"exp":"Phân tầng thực vật và kéo theo phân tầng động vật giúp phân chia ổ sinh thái ánh sáng, độ ẩm, thức ăn, nâng cao sức chứa và độ đa dạng của quần xã."},{"id":"MCQ-PH-067","topic":"physiology","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhịp Sinh học & Nội tiết","q":"Tuyến tùng (Pineal gland) ở não động vật có vú tiết ra hormone nào vào ban đêm để điều chỉnh chu kỳ thức - ngủ và nhịp sinh học ngày đêm?","opts":["Calcitonin.","Oxytocin.","Melatonin.","Glucagon."],"ans":2,"exp":"Melatonin được tiết tăng mạnh trong bóng tối dưới kiểm soát của nhân trên giao thoa thị giác (SCN), điều hòa đồng hồ sinh học ngày-đêm."},{"id":"MCQ-PH-068","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thế nước & Trao đổi Nước Tế bào","q":"Xét $3$ tế bào thực vật sống tiếp xúc với nhau: tế bào A có $\\Psi_s = -1.2\\text{ MPa}, \\Psi_p = +0.5\\text{ MPa}$; tế bào B có $\\Psi_s = -0.8\\text{ MPa}, \\Psi_p = +0.3\\text{ MPa}$; tế bào C có $\\Psi_s = -1.1\\text{ MPa}, \\Psi_p = +0.2\\text{ MPa}$. Chiều di chuyển tổng thể của dòng nước giữa $3$ tế bào này ngay tại thời điểm đó là:","opts":["Từ C sang A và từ A sang B.","Nước cân bằng đứng yên ở cả 3 tế bào.","Từ B sang A và từ B sang C; đồng thời từ A sang C ($\\Psi_B > \\Psi_A > \\Psi_C$).","Nước đi hoàn toàn vào B vì $\\Psi_s$ của B lớn nhất ($-0.8$)."],"ans":2,"exp":"Thế nước $\\Psi = \\Psi_s + \\Psi_p$: $\\Psi_A = -0.7\\text{ MPa}$; $\\Psi_B = -0.5\\text{ MPa}$; $\\Psi_C = -0.9\\text{ MPa}$. Nước luôn di chuyển từ nơi thế nước cao sang nơi thế nước thấp: $\\Psi_B (-0.5) > \\Psi_A (-0.7) > \\Psi_C (-0.9)$."},{"id":"MCQ-PH-069","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thế nước & Dung dịch Đường","q":"Thả một lát củ khoai tây vào cốc dung dịch đường saccarôzơ $0.4\\text{ M}$ ở $27^\\circ\\text{C}$ ($R \\cdot T \\approx 2.49\\text{ MPa}\\cdot\\text{L/mol}$, hệ số $i=1$). Sau $1$ giờ cân nặng lát khoai tây KHÔNG thay đổi chút nào (đạt trạng thái đẳng trương). Biết tế bào khoai tây khi đó bắt đầu co nguyên sinh nhẹ nên áp suất trương $\\Psi_p = 0$. Thế chất tan $\\Psi_s$ bên trong dịch tế bào khoai tây xấp xỉ:","opts":["$-1.0\\text{ MPa}$ ($\\approx -0.996\\text{ MPa}$).","$-0.4\\text{ MPa}$.","$+1.0\\text{ MPa}$.","$-2.5\\text{ MPa}$."],"ans":0,"exp":"Dung dịch ngoài $\\Psi_{ng} = -i C R T = -1 \\times 0.4 \\times 2.49 \\approx -0.996\\text{ MPa}$. Khi cân bằng không đổi khối lượng ($\\Psi_{tb} = \\Psi_{ng}$) và $\\Psi_p = 0 \\Rightarrow \\Psi_s = \\Psi_{tb} \\approx -0.996\\text{ MPa} \\approx -1.0\\text{ MPa}$."},{"id":"MCQ-PH-070","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp & Quang hô hấp","q":"Vì sao trong thí nghiệm đặt một cây $C_3$ (như cây đậu) và một cây $C_4$ (như cây ngô) vào chung một chuông thủy tinh kín được chiếu sáng liên tục ban đầu ở nồng độ $CO_2$ khí quyển ($0.04\\%$), sau một thời gian cây $C_3$ bị héo vàng và chết trước còn cây ngô $C_4$ vẫn sống xanh tốt?","opts":["Cây đậu không thực hiện được quang phân ly nước.","Điểm bù $CO_2$ của cây $C_4$ rất thấp ($\\approx 0-10\\text{ ppm}$) nên cây $C_4$ tiếp tục hút hết $CO_2$ xuống dưới điểm bù $CO_2$ của cây $C_3$ ($\\approx 40-50\\text{ ppm}$), làm cây $C_3$ hô hấp sáng và mất cacbon cho tới chết.","Ánh sáng bị thực vật $C_4$ biến đổi thành tia hồng ngoại giết cây $C_3$.","Cây ngô tiết độc tố qua lá tiêu diệt cây đậu ngay lập tức."],"ans":1,"exp":"Khi nồng độ $CO_2$ trong chuông kín tụt xuống dưới điểm bù $CO_2$ của cây $C_3$, quang hợp thực của cây $C_3$ âm trong khi cây $C_4$ vẫn tiếp tục cố định hữu hiệu lượng $CO_2$ còn lại."},{"id":"MCQ-PH-071","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thí nghiệm Quang hợp kinh điển","q":"Trong thí nghiệm tách lục lạp cô lập (thí nghiệm Hill năm 1937) đặt trong bóng tối hoặc có ánh sáng kèm chất nhận điện tử nhân tạo DCPIP (có màu xanh lam khi oxi hóa, mất màu khi bị khử) và KHÔNG hề có $CO_2$, hiện tượng nào chứng minh $O_2$ sinh ra từ nước chứ không phải từ $CO_2$?","opts":["Khi chiếu sáng vẫn có $O_2$ giải phóng ra và DCPIP mất màu xanh lam dù không hề cung cấp $CO_2$.","Không bao giờ có $O_2$ nếu thiếu khí $CO_2$.","Trong tối DCPIP mất màu nhanh gấp đôi ngoài sáng.","Khi chiếu sáng đường glucose vẫn hình thành ồ ạt không cần $CO_2$."],"ans":0,"exp":"Phản ứng Hill tách rời pha sáng (quang phân ly nước $\\rightarrow O_2$ và khử chất nhận điện tử) khỏi chu trình đồng hóa $CO_2$, kết hợp đồng vị $^{18}O$ khẳng định $O_2$ đến từ $H_2O$."},{"id":"MCQ-PH-072","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hô hấp ở C3","q":"Chu trình quang hô hấp (hô hấp sáng) ở thực vật $C_3$ sử dụng trực tiếp chuỗi phản ứng qua tuần tự $3$ bào quan nào trong tế bào thịt lá?","opts":["Ti thể $\\rightarrow$ Lizôxôm $\\rightarrow$ Trung thể.","Không bào $\\rightarrow$ Màng sinh chất $\\rightarrow$ Thành tế bào.","Nhân $\\rightarrow$ Lưới nội chất $\\rightarrow$ Bộ máy Golgi.","Lục lạp $\\rightarrow$ Peroxixôm $\\rightarrow$ Ti thể (và quay lại)."],"ans":3,"exp":"Enzyme RuBisCO gắn $O_2$ tạo axit glycolic ở lục lạp $\\rightarrow$ chuyển sang peroxixôm biến đổi thành glyxin $\\rightarrow$ sang ti thể giải phóng $CO_2, NH_3$ và chuyển thành serin quay lại chu trình thu hồi cacbon."},{"id":"MCQ-PH-073","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cơ chế Đóng Mở Khí khổng","q":"Khi rễ cây bị khô hạn thiếu nước, rễ và lá tăng tổng hợp nhanh axit abxixic ($ABA$). Cơ chế tế bào trực tiếp khiến $ABA$ gây đóng khí khổng khẩn cấp để giữ nước là:","opts":["$ABA$ gắn thụ thể tế bào bảo vệ làm mở kênh $Ca^{2+}$ và kích hoạt kênh xuất $Cl^-$, $K^+$ ra khỏi tế bào khí khổng, làm giảm áp suất thẩm thấu, nước thoát ra và khí khổng đóng.","$ABA$ bơm ồ ạt $K^+$ vào trong không bào khiến tế bào trương phồng lên.","$ABA$ chuyển toàn bộ tinh bột thành đường glucose trong tối.","$ABA$ làm thủng vách tế bào bảo vệ vĩnh viễn."],"ans":0,"exp":"$ABA$ khởi phát dòng thoát ion $Cl^-$ và $K^+$ khỏi tế bào khí khổng $\\rightarrow$ tăng thế nước nội bào $\\rightarrow$ nước thoát ra ngoài làm xẹp tế bào khí khổng $\\rightarrow$ đóng khe."},{"id":"MCQ-PH-074","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang chu kỳ & Phytocrom","q":"Một loài thực vật NGÀY DÀI (cần thời gian tối liên tục ngắn hơn thời gian tối tới hạn $11$ giờ để ra hoa) được trồng trong điều kiện $10$ giờ sáng / $14$ giờ tối. Nếu ở chính giữa đêm tối $14$ giờ người ta chiếu lóe ánh sáng Đỏ ($R, 660\\text{ nm}$) rồi ngay sau đó chiếu lóe ánh sáng Đỏ xa ($FR, 730\\text{ nm}$), trạng thái ra hoa của cây sẽ như thế nào?","opts":["Ra hoa nhanh gấp đôi vì $P_r$ kích thích trực tiếp cây ngày dài.","Ra hoa rực rỡ vì có lóe ánh sáng đỏ kích thích.","KHÔNG ra hoa (vì xung cuối cùng là Đỏ xa chuyển $P_{fr} \\rightarrow P_r$, khôi phục trạng thái đêm tối dài $14$ giờ liên tục).","Chết héo ngay lập tức do xung khắc bước sóng."],"ans":2,"exp":"Ánh sáng $R$ ($660\\text{ nm}$) ngắt đêm tạo dạng $P_{fr}$ kích thích cây ngày dài ra hoa, nhưng xung $FR$ ($730\\text{ nm}$) ngay sau đó lại chuyển $P_{fr}$ về $P_r$, xóa hiệu ứng ngắt đêm nên đêm tối vẫn dài $14\\text{ h} > 11\\text{ h}$ $\\Rightarrow$ không ra hoa."},{"id":"MCQ-PH-075","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cố định Đạm Sinh học","q":"Tại sao trong nốt sần rễ cây họ Đậu có chứa hàm lượng lớn sắc tố màu đỏ Leghemoglobin?","opts":["Leghemoglobin thay thế diệp lục để thực hiện quang hợp dưới lòng đất.","Leghemoglobin liên kết chặt với $O_2$ tự do giúp giữ nồng độ $O_2$ rất thấp để bảo vệ enzyme Nitrogenase khỏi bị mất hoạt tính trong khi vẫn cung cấp đủ $O_2$ cho hô hấp tạo ATP của vi khuẩn cộng sinh.","Leghemoglobin trực tiếp oxy hóa $N_2$ thành $HNO_3$.","Leghemoglobin giúp vận chuyển đường saccarôzơ lên thân cây."],"ans":1,"exp":"Enzyme nitrogenase xúc tác $N_2 + 8H^+ + 8e^- + 16\\text{ ATP} \\rightarrow 2NH_3 + H_2 + 16\\text{ ADP} + 16P_i$ bị $O_2$ ức chế không thuận nghịch, nên leghemoglobin đóng vai trò đệm điều phối $O_2$ tinh vi."},{"id":"MCQ-PH-076","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ Tim & Cung lượng tim","q":"Một vận động viên khi nghỉ ngơi có nhịp tim $HR = 50\\text{ lần/phút}$, thể tích cuối tâm trương $EDV = 140\\text{ ml}$ và thể tích cuối tâm thu $ESV = 40\\text{ ml}$. Thể tích tâm thu ($SV$), phân suất tống máu ($EF$) và cung lượng tim ($CO$) của vận động viên này lần lượt là:","opts":["$SV = 40\\text{ ml}$; $EF = 28.6\\%$; $CO = 2.0\\text{ lít/phút}$.","$SV = 100\\text{ ml}$; $EF \\approx 71.4\\%$; $CO = 5.0\\text{ lít/phút}$.","$SV = 100\\text{ ml}$; $EF = 40.0\\%$; $CO = 10.0\\text{ lít/phút}$.","$SV = 140\\text{ ml}$; $EF = 100\\%$; $CO = 7.0\\text{ lít/phút}$."],"ans":1,"exp":"$SV = EDV - ESV = 140 - 40 = 100\\text{ ml}$. Phân suất tống máu $EF = \\frac{100}{140} \\approx 71.4\\%$. Cung lượng tim $CO = HR \\times SV = 50 \\times 100 = 5000\\text{ ml/phút} = 5.0\\text{ L/phút}$."},{"id":"MCQ-PH-077","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chu kỳ Hoạt động Tim","q":"Ở người bình thường có nhịp tim $75\\text{ nhịp/phút}$ (một chu kỳ tim kéo dài $0.8\\text{ s}$: co nhĩ $0.1\\text{ s}$, co thất $0.3\\text{ s}$, dãn chung $0.4\\text{ s}$). Trong một chu kỳ tim, khoảng thời gian TÂM NHĨ được nghỉ ngơi hoàn toàn (dãn) và TÂM THẤT được nghỉ ngơi hoàn toàn lần lượt kéo dài bao lâu?","opts":["Tâm nhĩ dãn $0.4\\text{ s}$; tâm thất dãn $0.4\\text{ s}$.","Tâm nhĩ dãn $0.3\\text{ s}$; tâm thất dãn $0.1\\text{ s}$.","Tâm nhĩ dãn $0.5\\text{ s}$; tâm thất dãn $0.7\\text{ s}$.","Tâm nhĩ dãn $0.7\\text{ s}$; tâm thất dãn $0.5\\text{ s}$."],"ans":3,"exp":"Trong $0.8\\text{ s}$: nhĩ chỉ co $0.1\\text{ s}$ nên được dãn $0.8 - 0.1 = 0.7\\text{ s}$; thất chỉ co $0.3\\text{ s}$ nên được dãn $0.8 - 0.3 = 0.5\\text{ s}$ — nhờ đó tim hoạt động suốt đời mà không mỏi."},{"id":"MCQ-PH-078","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cân bằng Starling tại Mao mạch","q":"Tại đầu tiểu tĩnh mạch của một giường mao mạch, áp suất thủy tĩnh máu là $P_c = 15\\text{ mmHg}$, áp suất keo huyết tương là $\\pi_c = 25\\text{ mmHg}$, áp suất thủy tĩnh dịch kẽ $P_i = 0$ và áp suất keo dịch kẽ $\\pi_i = 0$. Dòng dịch sẽ di chuyển theo chiều nào?","opts":["Lọc đẩy dịch từ mao mạch ra dịch kẽ với áp lực $10\\text{ mmHg}$.","Cân bằng không trao đổi dịch ($0\\text{ mmHg}$).","Tái hấp thu đi từ dịch kẽ vào lòng mao mạch với áp lực thuần $10\\text{ mmHg}$.","Đẩy nước ra dịch kẽ với áp lực $40\\text{ mmHg}$."],"ans":2,"exp":"Áp suất lọc thuần $P_{net} = (P_c - P_i) - (\\pi_c - \\pi_i) = 15 - 25 = -10\\text{ mmHg}$. Dấu âm biểu thị chiều tái hấp thu dịch từ kẽ mô quay lại mao mạch."},{"id":"MCQ-PH-079","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Suy Tim & Phù Nề","q":"Bệnh nhân bị xơ gan nặng làm gan giảm tổng hợp albumin huyết tương nghiêm trọng thường có triệu chứng phù nề toàn thân và tràn dịch màng bụng (cổ trướng). Nguyên nhân trực tiếp theo cơ chế trao đổi dịch mao mạch là:","opts":["Thận lọc tăng tốc $10$ lần gây ứ đọng protein ở cơ xương.","Nồng độ albumin giảm mạnh làm giảm áp suất keo huyết tương ($\\pi_c$ giảm), khiến nước dễ bị đẩy ra mô kẽ nhiều hơn là được tái hấp thu vào mao mạch.","Áp suất keo huyết tương tăng lên gấp $3$ lần bình thường.","Huyết áp động mạch tụt xuống $0\\text{ mmHg}$ nên máu ngừng lưu thông."],"ans":1,"exp":"Albumin đóng góp khoảng $70-80\\%$ áp suất keo huyết tương giữ nước trong lòng mạch; giảm albumin gây giảm $\\pi_c$, mất cân bằng Starling dẫn tới ứ dịch mô kẽ (phù)."},{"id":"MCQ-PH-080","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điện thế Nghỉ Tế bào Thần kinh","q":"Động lực trực tiếp giúp duy trì sự chênh lệch nồng độ ion $K^+$ cao bên trong và $Na^+$ cao bên ngoài màng nơron ở trạng thái điện thế nghỉ ($\\approx -70\\text{ mV}$) trong thời gian dài là:","opts":["Sự khuếch tán thụ động $Na^+$ ồ ạt từ trong ra ngoài không cần ATP.","Hoạt động của bơm $Na^+/K^+$ ATPase bơm chủ động $3\\text{ Na}^+$ ra ngoài và $2\\text{ K}^+$ vào trong cho mỗi phân tử ATP thủy phân.","Các đại phân tử protein mang điện dương khổng lồ thoát ra khỏi tế bào.","Cổng $Na^+$ điện thế luôn mở toang $100\\%$ khi nghỉ."],"ans":1,"exp":"Ngoài tính thấm chọn lọc cao với $K^+$ qua kênh rò rỉ (yếu tố chính tạo chênh áp âm lúc tức thời), bơm $Na^+/K^+$ tiêu tốn ATP giữ gradient nồng độ $Na^+, K^+$ ổn định bền vững và đóng góp trực tiếp một phần điện tích âm trong màng ($3+$ ra, $2+$ vào)."},{"id":"MCQ-PH-081","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điện thế Hoạt động","q":"Trong quá trình hình thành điện thế hoạt động ở sợi trục thần kinh, giai đoạn MẤT PHÂN CỰC (khử cực nhanh từ $-70\\text{ mV}$ vọt lên $+30\\text{ mV}$) do sự kiện nào chi phối chủ yếu?","opts":["Đóng toàn bộ các kênh ion và kích hoạt bơm $Na^+/K^+$.","Mở nhanh các kênh $K^+$ cho dòng $K^+$ đi ra ngoài tế bào.","Mở nhanh ồ ạt các kênh $Na^+$ cổng điện thế cho dòng ion $Na^+$ khuếch tán vào trong tế bào.","Ion $Cl^-$ tràn vào trong màng tế bào."],"ans":2,"exp":"Khi đạt ngưỡng kích thích ($\\approx -55\\text{ mV}$), kênh $Na^+$ mở đồng loạt (phản hồi dương) khiến $Na^+$ tràn vào đảo cực màng đạt đỉnh $+30\\text{ mV}$."},{"id":"MCQ-PH-082","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thời kỳ Trơ Tuyệt đối","q":"Tại sao xung thần kinh bình thường chỉ lan truyền theo một chiều dọc sợi trục từ thân tế bào về cúc tận cùng mà không dội ngược trở lại phần màng vừa đi qua?","opts":["Vì thân tế bào không có kênh $K^+$.","Vì bao myelin biến mất sau mỗi xung đi qua.","Vùng màng phía sau vừa phát sinh điện thế hoạt động đang rơi vào thời kỳ trơ tuyệt đối (cổng bất hoạt kênh $Na^+$ vẫn đang đóng chặt) nên không thể tái kích thích ngay.","Vì cúc xinap hút điện thế bằng từ trường."],"ans":2,"exp":"Cổng bất hoạt của kênh $Na^+$ đóng trong suốt pha tái phân cực tạo thời kỳ trơ tuyệt đối, ngăn điện thế hoạt động truyền ngược chiều và giới hạn tần số phát xung tối đa."},{"id":"MCQ-PH-083","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Co Cơ Vân","q":"Trong cơ chế co cơ vân theo mô hình sợi trượt, vai trò trực tiếp của phân tử ATP khi gắn vào đầu cầu nối myosin là:","opts":["Tạo lớp mỡ bao quanh sợi cơ.","Phân hủy hoàn toàn sợi actin thành axit amin.","Trực tiếp chuyển thành canxi đi vào lưới cơ tương.","Làm đầu myosin tách khỏi vị trí gắn trên sợi actin (nếu thiếu ATP, cầu nối myosin bị khóa cứng với actin gây hiện tượng co cứng tử thi), sau đó thủy phân ATP để lên cò đầu myosin."],"ans":3,"exp":"Khi chết tế bào cạn kiệt ATP khiến đầu myosin không thể tách khỏi actin, dẫn đến hiện tượng cứng cơ sau tử vong (Rigor mortis)."},{"id":"MCQ-PH-084","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Co Cơ Vân","q":"Ion $Ca^{2+}$ được phóng thích từ lưới nội cơ tương (SR) vào bào tương tế bào cơ vân đã kích khởi sự co cơ bằng cách nào?","opts":["Gắn trực tiếp vào đầu myosin đẩy cơ dãn ra tối đa.","Thủy phân trực tiếp đường glycogen thành axit lactic.","Thay thế phân tử ATP trong ti thể.","Gắn vào tiểu phần Troponin C, làm xoay phức hợp Tropomyosin bộc lộ vị trí gắn myosin trên sợi Actin."],"ans":3,"exp":"Khi nghỉ, tropomyosin che khuất điểm gắn trên actin; $Ca^{2+}$ gắn troponin làm dịch chuyển tropomyosin mở đường cho myosin hình thành cầu nối trượt."},{"id":"MCQ-PH-085","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa Tiêu hóa & Nội tiết","q":"Khi dịch vị axit từ dạ dày được đẩy xuống tá tràng (pH thấp), tế bào biểu mô tá tràng tăng tiết hormone nào đi vào máu để kích thích tuyến tụy ngoại tiết tiết dịch giàu ion $HCO_3^-$ trung hòa axit?","opts":["Insulin.","Oxytocin.","Gastrin.","Secretin."],"ans":3,"exp":"Secretin (hormone đầu tiên được phát hiện trong lịch sử) đáp ứng với axit HCl ở tá tràng, kích thích ống dẫn tụy tiết bicarbonat trung hòa pH bảo vệ niêm mạc ruột và tối ưu cho enzyme tụy."},{"id":"MCQ-PH-086","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Máu & Hô hấp","q":"Khoảng $70\\%$ lượng khí $CO_2$ sinh ra từ hô hấp tế bào mô được vận chuyển trong máu về phổi dưới dạng hóa học nào?","opts":["Ion bicarbonat ($HCO_3^-$) hòa tan trong huyết tương (sau khi chuyển đổi nhờ enzyme carbonic anhydrase trong hồng cầu).","Khí $CO_2$ tự do dạng bọt khí trong động mạch.","Liên kết hóa trị bền vững không tách rời với nhân sắt $Fe^{2+}$ của Heme.","Axit axetic tự do."],"ans":0,"exp":"Trong hồng cầu, $CO_2 + H_2O \\xrightarrow{CA} H_2CO_3 \\rightarrow H^+ + HCO_3^-$. Sau đó $HCO_3^-$ trao đổi với $Cl^-$ ra huyết tương (chuyển dịch Clorua) về tới phổi để giải phóng lại $CO_2$."},{"id":"MCQ-PH-087","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Bệnh lý Nội môi & pH Máu","q":"Một bệnh nhân bị nôn mửa liên tục và dữ dội suốt nhiều ngày làm mất một lượng lớn dịch vị giàu axit $HCl$. Rối loạn thăng bằng kiềm-toan nào có nguy cơ xảy ra ở bệnh nhân này?","opts":["Giảm pH máu xuống dưới $6.8$ ngay lập tức.","Tăng dự trữ kiềm tụt về $0$.","Nhiễm toan hô hấp nặng do tăng $HCl$ trong máu.","Nhiễm kiềm chuyển hóa (tăng pH máu do mất lượng lớn ion $H^+$ qua dịch nôn và tăng tái hấp thu $HCO_3^-$)."],"ans":3,"exp":"Mất ion $H^+$ từ dịch dạ dày khiến cân bằng đệm dịch chuyển tăng $HCO_3^-$ huyết tương $\\rightarrow$ nhiễm kiềm chuyển hóa."},{"id":"MCQ-PH-088","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hệ Miễn dịch Tế bào","q":"Phân tử MHC lớp I (Major Histocompatibility Complex Class I) có mặt trên hầu hết mọi tế bào có nhân của cơ thể người có chức năng trình diện mảnh kháng nguyên nội sinh (như protein virus tổng hợp bên trong tế bào) cho tế bào nào nhận diện tiêu diệt?","opts":["Tế bào Lympho T gây độc ($T_C$ mang thụ thể $CD8^+$).","Tế bào thần kinh đệm.","Tiểu cầu tuần hoàn.","Tế bào Hồng cầu trưởng thành."],"ans":0,"exp":"MHC-I gắn mảnh peptide nội bào trình diện cho $CD8^+$ ($T_C$) tiết perforin và granzyme kích hoạt apoptosis tiêu diệt tế bào nhiễm virus hoặc tế bào ung thư; MHC-II chỉ có ở tế bào APC để trình diện cho $CD4^+$."},{"id":"MCQ-PH-089","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Miễn dịch Nguyên phát & Thứ phát","q":"Việc tiêm vắc xin giúp cơ thể chống lại tác nhân gây bệnh hiệu quả khi gặp phải mầm bệnh thật sự lần sau dựa trên cơ chế miễn dịch nào?","opts":["Tạo sẵn các tế bào nhớ miễn dịch (Memory B & Memory T cells) đặc hiệu, giúp đáp ứng miễn dịch thứ phát xảy ra cực nhanh, mạnh mẽ với lượng kháng thể lớn hơn nhiều lần so với lần đầu.","Chứa sẵn kháng sinh tổng hợp tồn tại suốt $80$ năm trong máu.","Ức chế vĩnh viễn hoạt động của tủy xương và tuyến ức.","Làm thay đổi trình tự ADN của toàn bộ tế bào cơ bắp thành kháng nguyên."],"ans":0,"exp":"Vắc xin mô phỏng lần tiếp xúc thứ nhất (không gây bệnh nặng) để hình thành quần thể tế bào trí nhớ miễn dịch sống lâu năm."},{"id":"MCQ-PH-090","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nội tiết Điều hòa Canxi máu","q":"Khi nồng độ $Ca^{2+}$ trong máu người giảm xuống thấp bất thường, tuyến cận giáp tăng tiết hormone $PTH$ (Parathyroid hormone) tác động đồng bộ như thế nào?","opts":["Ức chế hấp thu $Ca^{2+}$ ở ruột và đẩy toàn bộ $Ca^{2+}$ ra nước tiểu.","Kích thích tế bào hủy xương giải phóng $Ca^{2+}$, tăng tái hấp thu $Ca^{2+}$ tại thận và kích hoạt vitamin D để tăng hấp thu $Ca^{2+}$ từ ruột non.","Ngừng bài tiết dịch tụy hoàn toàn.","Kích thích lắng đọng $Ca^{2+}$ ồ ạt vào xương như Calcitonin."],"ans":1,"exp":"PTH nâng nồng độ $Ca^{2+}$ huyết tương lên mức bình thường (đối kháng với Calcitonin của tuyến giáp vốn làm hạ $Ca^{2+}$ máu)."},{"id":"MCQ-PH-091","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Sinh sản Động vật","q":"Hiện tượng 'đỉnh $LH$' (LH surge) tăng vọt đột ngột vào khoảng ngày thứ $13-14$ của chu kỳ kinh nguyệt $28$ ngày ở phụ nữ đóng vai trò sinh lý quyết định nào?","opts":["Kích thích bong tróc toàn bộ niêm mạc tử cung gây hành kinh ngay tức thì.","Ức chế hoàn toàn sự bài tiết Progesterone.","Chuyển hóa tinh trùng thành tế bào Xôma.","Kích thích nang trứng chín vỡ ra giải phóng noãn bào bậc II (sự rụng trứng) và thúc đẩy nang vỡ biến thành thể vàng."],"ans":3,"exp":"Estrogen tăng cao kéo dài cuối pha nang trứng chuyển từ ức chế ngược âm tính sang kích thích ngược dương tính lên vùng dưới đồi-tuyến yên, gây đỉnh $LH$ phóng noãn."},{"id":"MCQ-PH-092","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Ổ Sinh thái (Hutchinson)","q":"Trong nghiên cứu kinh điển của Joseph Connell trên hai loài hà đá vùng triều Scotland (*Chthamalus stellatus* và *Balanus balanoides*): loài *Chthamalus* có thể sống ở cả vùng triều cao lẫn vùng triều thấp nếu loại bỏ *Balanus*, nhưng thực tế ngoài tự nhiên chỉ sống ở vùng triều cao. Khẳng định nào diễn giải chính xác?","opts":["Ổ sinh thái thực tế luôn rộng lớn hơn ổ sinh thái cơ bản.","*Chthamalus* hoàn toàn bị giết chết bởi nước biển nếu xuống vùng triều thấp.","Vùng triều cao cộng vùng triều thấp là Ổ SINH THÁI CƠ BẢN của *Chthamalus*; việc bị *Balanus* cạnh tranh lấn át khiến *Chthamalus* chỉ còn chiếm giữ được vùng triều cao — đó là Ổ SINH THÁI THỰC TẾ của nó.","*Balanus* là loài cộng sinh bắt buộc giúp *Chthamalus* leo cao."],"ans":2,"exp":"Ổ sinh thái cơ bản (Fundamental niche) phản ánh giới hạn sinh lý tiềm năng; ổ sinh thái thực tế (Realized niche) bị thu hẹp dưới tác động tương tác cạnh tranh, vật ăn thịt..."},{"id":"MCQ-PH-093","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Năng suất Sinh học Hệ sinh thái","q":"Trong sinh thái học hệ sinh thái, năng suất sinh học sơ cấp tinh ($NPP$) liên hệ với năng suất sinh học sơ cấp thô ($GPP$) và năng lượng hô hấp của thực vật sản xuất ($R_a$) qua phương trình nào?","opts":["$NPP = \\frac{R_a}{GPP}$.","$NPP = GPP + R_a$.","$NPP = GPP \\times R_a$.","$NPP = GPP - R_a$."],"ans":3,"exp":"$GPP$ là tổng năng lượng quang hợp cố định được; trừ phần thực vật tự sử dụng cho hô hấp $R_a$, phần sinh khối mới tích lũy $NPP$ mới sẵn sàng cho sinh vật tiêu thụ và phân giải."},{"id":"MCQ-PH-094","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tháp Sinh khối Đảo ngược","q":"Tại vùng biển khơi đại dương trong mùa xuân, tại sao khi đo sinh khối ở một thời điểm tức thời lại thường thu được tháp sinh khối LỘN NGƯỢC (sinh khối thực vật phù du nhỏ hơn sinh khối động vật phù du ăn chúng)?","opts":["Do thực vật phù du kích thước hiển vi có tốc độ sinh sản và quay vòng (turnover) cực nhanh, bị ăn liên tục ngay khi vừa sinh ra nên năng suất tích lũy theo thời gian vẫn rất cao đủ nuôi tầng trên.","Do ở đại dương động vật phù du tự quang hợp không cần thực vật phù du.","Do năng lượng bị mất hết ở đáy tháp và tự sinh ra thêm ở tầng trên.","Do định luật bảo toàn năng lượng không áp dụng dưới nước."],"ans":0,"exp":"Tháp sinh khối đo trạng thái tĩnh (g/m$^2$ tại 1 thời điểm) nên có thể lộn ngược nếu SVSX vòng đời rất ngắn; còn tháp năng lượng đo dòng chảy theo thời gian (kcal/m$^2$/năm) luôn chuẩn."},{"id":"MCQ-PH-095","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chỉ số Hiệu suất Sinh thái","q":"Một con sâu ăn lá tiêu thụ lượng lá cây chứa $200\\text{ J}$ năng lượng ($I$). Sau tiêu hóa, nó thải qua phân $100\\text{ J}$ ($F$) và sử dụng cho hô hấp $60\\text{ J}$ ($R$), phần còn lại chuyển thành tăng trưởng mô cơ thể ($P$). Hiệu suất đồng hóa ($AE$) và hiệu suất sản xuất thực ($PE$) của con sâu này lần lượt là:","opts":["$AE = 20\\%$ và $PE = 50\\%$.","$AE = 70\\%$ và $PE = 30\\%$.","$AE = 50\\%$ và $PE = 40\\%$.","$AE = 40\\%$ và $PE = 20\\%$."],"ans":2,"exp":"Lượng đồng hóa $A = I - F = 200 - 100 = 100\\text{ J}$. Sản lượng mới $P = A - R = 100 - 60 = 40\\text{ J}$. Vậy $AE = \\frac{A}{I} = \\frac{100}{200} = 50\\%$; $PE = \\frac{P}{A} = \\frac{40}{100} = 40\\%$."},{"id":"MCQ-PH-096","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Khuếch đại Sinh học (Biomagnification)","q":"Trong một hệ sinh thái hồ nhiễm thuốc trừ sâu DDT không phân hủy sinh học: Nước hồ ($0.000003\\text{ ppm}$) $\\rightarrow$ Động vật phù du $\\rightarrow$ Cá nhỏ $\\rightarrow$ Cá lớn $\\rightarrow$ Chim bói cá ăn cá. Khi phân tích mẫu mô mỡ, nồng độ DDT cao nhất gấp hàng triệu lần nước hồ sẽ tập trung ở sinh vật nào?","opts":["Cá nhỏ ở tầng mặt.","Chim bói cá (bậc dinh dưỡng cao nhất ở đỉnh chuỗi thức ăn).","Động vật phù du ở bậc tiêu thụ cấp $1$.","Nước hồ tinh khiết."],"ans":1,"exp":"Chất độc khó phân hủy tích lũy trong mô mỡ được dồn tích qua mỗi bậc tiêu thụ lên bậc cao hơn do sinh khối ở các bậc trên cô đặc năng lượng và chất từ lượng lớn thức ăn bậc dưới."},{"id":"MCQ-PH-097","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tương quan Tỉ lệ Hormone Thực vật","q":"Trong nuôi cấy mô tế bào thực vật (*in vitro*), nếu muốn kích thích mô sẹo (Callus) phân hóa mạnh mẽ thành CHỒI thân lá, người kỹ thuật viên cần điều chỉnh tỉ lệ nồng độ cặp hormone nào như thế nào?","opts":["Tỉ lệ $\\frac{\\text{Cytokinin}}{\\text{Auxin}}$ cao (lượng Cytokinin lớn hơn Auxin).","Tỉ lệ $\\frac{\\text{Auxin}}{\\text{Cytokinin}}$ rất cao để ra chồi.","Chỉ dùng $100\\%$ Axit Abxixic ($ABA$) và không thêm gì khác.","Chỉ dùng khí Etilen nguyên chất ở áp suất cao."],"ans":0,"exp":"Theo phát hiện kinh điển của Skoog và Miller: Auxin cao/Cytokinin thấp kích thích ra rễ; Cytokinin cao/Auxin thấp kích thích tái sinh chồi; tỷ lệ cân bằng giữ dạng mô sẹo (callus)."},{"id":"MCQ-PH-098","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hệ Thần kinh Thực vật (Tự chủ)","q":"Tác dụng sinh lý điển hình của hệ thần kinh ĐỐI GIAO CẢM (Parasympathetic) — sử dụng Acetylcholine ở cơ quan đích — lên hoạt động tim và hệ tiêu hóa là gì?","opts":["Làm giảm nhịp tim, co đồng tử, đồng thời tăng cường nhu động ruột và tiết dịch tiêu hóa (trạng thái 'nghỉ ngơi và tiêu hóa').","Ức chế toàn bộ tuyến nước bọt gây khô miệng.","Giải phóng ồ ạt Adrenalin gây giãn phế quản cực đại.","Làm tim đập nhanh dồn dập, giãn đồng tử và ngừng nhu động ruột."],"ans":0,"exp":"Hệ giao cảm ưu thế trong vận động khẩn cấp ('fight or flight'), còn hệ đối giao cảm bảo tồn năng lượng và thúc đẩy tiêu hóa hấp thu ('rest and digest')."},{"id":"MCQ-PH-099","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp & Đệm Carbonic","q":"Tại sao khi một người lặn sâu dưới nước muốn nhịn thở lâu hơn, việc cố ý hít thở thật nhanh và sâu liên tục (tăng thông khí chủ động) ngay trước khi lặn lại CỰC KỲ NGUY HIỂM có thể gây ngất xỉu dưới nước (Shallow-water blackout)?","opts":["Thở gấp biến đổi hemoglobin thành methemoglobin.","Thở gấp trước khi lặn làm thải giảm mạnh $pCO_2$ máu (mất kích thích trung khu hô hấp gây muốn thở) dù $O_2$ trong máu gần như không tăng thêm; khi lặn $pO_2$ tụt xuống gây bất tỉnh thiếu oxy não TRƯỚC KHI $pCO_2$ kịp tăng đủ để báo động ngoi lên.","Thở gấp làm tăng áp suất $CO_2$ gấp $10$ lần khiến phổi vỡ.","Thở gấp làm phổi hút hết nitơ thay oxy."],"ans":1,"exp":"Cảm giác bức bối muốn thở do $pCO_2$ (và $H^+$ dịch não tủy) điều phối nhạy hơn nhiều so với thiếu $O_2$; xả cạn $CO_2$ làm tắt chuông cảnh báo sinh tồn."},{"id":"MCQ-PH-100","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Ánh sáng & Quang hợp","q":"Tại sao lá cây màu xanh lục (không hấp thụ nhiều bước sóng xanh lục mà phản xạ/cho xuyên qua)? Bước sóng ánh sáng nào tạo ra đỉnh hiệu suất quang hợp (Phổ tác dụng) cao nhất cho thực vật bậc cao?","opts":["Chỉ ánh sáng xanh lục ($530-560\\text{ nm}$).","Ánh sáng đỏ ($\\approx 660-680\\text{ nm}$) và ánh sáng xanh tím ($\\approx 430-450\\text{ nm}$).","Tia X và tia gamma.","Ánh sáng hồng ngoại xa trên $1000\\text{ nm}$."],"ans":1,"exp":"Thực nghiệm Engelmann và phổ hấp thụ diệp lục $a, b$ cùng carotenoid xác nhận vùng đỏ và xanh tím cung cấp năng lượng hiệu quả nhất cho pha sáng quang hợp."},{"id":"MCQ-PH-101","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Tim & Điện tâm đồ (ECG)","q":"Trên bản ghi điện tâm đồ (ECG) bình thường của người, phức bộ sóng nhọn $QRS$ biểu thị cho sự kiện điện sinh lý nào của tim?","opts":["Sự khử cực lan truyền nhanh khắp cơ hai TÂM THẤT (chuẩn bị cho thất co tống máu).","Sự tái phân cực chậm của tâm thất.","Sự khử cực của hai tâm nhĩ.","Thời điểm đóng van nhĩ-thất cuối kỳ dãn chung."],"ans":0,"exp":"Sóng P tương ứng khử cực tâm nhĩ; phức bộ QRS phản ánh khử cực tâm thất (che lấp luôn tái phân cực nhĩ); sóng T tương ứng tái phân cực tâm thất."},{"id":"MCQ-PH-102","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa Áp suất Thẩm thấu Thận","q":"Tại quai Henle trong nephron thận động vật có vú, cơ chế nào cho phép thận tạo ra nước tiểu CÔ ĐẶC ưu trương hơn hẳn huyết tương nhằm tiết kiệm nước trên cạn?","opts":["Ống lượn gần bơm toàn bộ muối vào lòng ống.","Cầu thận trực tiếp lọc urê nguyên chất dạng rắn.","Cơ chế tăng nồng độ ngược dòng (Countercurrent multiplier) giữa nhánh xuống thấm nước và nhánh lên không thấm nước nhưng bơm chủ động $Na^+, Cl^-$ ra vùng tủy thận, tạo gradient áp suất thẩm thấu tủy thận cực cao.","Tất cả mọi đoạn của nephron đều thấm nước như nhau."],"ans":2,"exp":"Động lực quai Henle + mạch thẳng vasa recta + urê từ ống góp thiết lập môi trường ưu trương tới $1200\\text{ mOsm/L}$ ở tủy sâu để $ADH$ tái hấp thu nước tại ống góp."},{"id":"MCQ-PH-103","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thực vật & Trao đổi Khoáng","q":"Khi bón lượng phân đạm ($NH_4NO_3$) quá liều cao đột ngột vào đất quanh gốc rau non mà không tưới đủ nước, cây dễ bị 'xót phân', héo rũ và chết vì nguyên nhân sinh lý nào?","opts":["Rễ cây biến đổi trực tiếp thành tinh bột.","Nồng độ muối đất quá cao làm dung dịch đất trở nên ưu trương (thế nước đất thấp hơn thế nước rễ), khiến rễ không hút được nước thậm chí bị mất nước ngược ra đất (hạn sinh lý).","Phân đạm làm cháy rễ theo đúng nghĩa phản ứng phát lửa.","Khí khổng mở toang vĩnh viễn không bao giờ đóng."],"ans":1,"exp":"Thế chất tan dung dịch đất âm quá sâu cản trở sự thẩm thấu nước vào lông hút, gây co nguyên sinh và héo rũ dù đất vẫn ẩm (hạn sinh lý)."},{"id":"MCQ-PH-104","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp & Điểm bão hòa","q":"So sánh hai nhóm thực vật cùng sống trong rừng nhiệt đới: cây ưa sáng (trên tán cao) và cây ưa bóng (mọc dưới thảm tán rừng). Điểm bù ánh sáng và điểm bão hòa ánh sáng của cây ưa BÓNG thường có đặc điểm nào?","opts":["Đều CAO gấp $5$ lần cây ưa sáng.","Bằng nhau tuyệt đối ở mọi cường độ ánh sáng.","Cây ưa bóng có cường độ hô hấp cực mạnh nên điểm bù rất cao.","Đều THẤP hơn hẳn so với cây ưa sáng (thích nghi với cường độ chiếu sáng yếu dưới tán rừng, có diệp lục b cao giúp bắt ánh sáng tán xạ hiệu quả)."],"ans":3,"exp":"Cây ưa bóng giữ mức hô hấp nền thấp và tăng diện tích lá/diệp lục b để đạt điểm bù sớm ngay ở ánh sáng yếu, đồng thời bão hòa sớm."},{"id":"MCQ-PH-105","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thính giác Động vật","q":"Cấu trúc nào trong ốc tai (tai trong) của động vật có vú chứa các tế bào lông cảm giác uốn cong chạm màng mái khi sóng âm rung màng đáy, biến đổi dao động cơ học thành xung điện thế thần kinh?","opts":["Màng nhĩ.","Ống bán khuyên trên.","Xương búa và xương đe.","Cơ quan Corti."],"ans":3,"exp":"Rung động dịch ngoại/nội dịch ốc tai làm dao động màng đáy tại vùng tần số tương ứng, ép lông rung của tế bào cảm giác trong cơ quan Corti mở kênh ion cơ học."},{"id":"MCQ-PH-106","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh thái Thích nghi Sinh vật (Quy tắc Bergmann - Allen)","q":"Cáo Bắc Cực (*Vulpes lagopus*) có kích thước thân chắc đậm với đôi tai ngắn nhỏ xíu, trong khi cáo sa mạc (*Vulpes zerda*) sống vùng nóng lại mảnh khảnh và có đôi tai rất to dài. Hiện tượng hình thái thích nghi nhiệt này tuân theo cặp quy tắc sinh thái nào?","opts":["Quy tắc Gause và quy tắc Leibig.","Quy tắc chuyển bậc dinh dưỡng $10\\%$.","Quy tắc Hardy-Weinberg và quy tắc Morgan.","Quy tắc Bergmann (động vật đẳng nhiệt vùng lạnh thường có kích thước cơ thể lớn hơn, giảm tỉ số $S/V$) và quy tắc Allen (phần phụ nhô ra như tai, đuôi vùng lạnh thường ngắn nhỏ lại để giảm mất nhiệt)."],"ans":3,"exp":"Giảm tỷ lệ diện tích bề mặt trên thể tích ($S/V$) và thu gọn các phần nhô giúp giữ nhiệt ở vùng cực; ngược lại, tai rộng nhiều mao mạch ở sa mạc giúp tỏa nhiệt hiệu quả."},{"id":"MCQ-PH-107","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Đông vật & Độc chất học","q":"Các loại thuốc trừ sâu gốc phospho hữu cơ (Organophosphate) hoặc chất độc thần kinh Sarin gây co giật cứng cơ hô hấp và tử vong nhanh do cơ chế nào tại synap thần kinh?","opts":["Phong bế toàn bộ kênh $Ca^{2+}$ ở tim làm ngừng tim thì tâm trương ngay lập tức.","Biến đổi $O_2$ thành khí cacbonic trong phế nang.","Phá hủy ngay lập tức thụ thể Insulin trên tế bào gan.","Ức chế không thuận nghịch enzyme Acetylcholinesterase tại khe xinap, khiến Acetylcholine tích tụ ứ đọng gây kích thích khử cực liên tục màng sau xinap."],"ans":3,"exp":"Khi Acetylcholinesterase bị bất hoạt, ACh không bị thủy phân kịp thời dẫn đến kích thích quá mức (cholinergic crisis) làm tê liệt cơ hoành."},{"id":"MCQ-PH-108","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chuỗi thức ăn & Độ dài Chuỗi","q":"Trong tự nhiên, một chuỗi thức ăn hiếm khi kéo dài quá $4$ đến $5$ bậc dinh dưỡng vì nguyên nhân chính nào?","opts":["Động vật bậc cao không biết săn mồi kích thước nhỏ.","Các sinh vật phân giải chặn không cho bậc $5$ lấy thức ăn.","Năng lượng bị thất thoát quá lớn ($\\sim 90\\%$) qua mỗi bước chuyển bậc dinh dưỡng nên lượng năng lượng còn lại ở bậc $5-6$ quá ít không đủ duy trì ổn định một quần thể sinh vật.","Số lượng loài sinh vật sản xuất chỉ tối đa $5$ loài."],"ans":2,"exp":"Giả thuyết năng lượng (Energetic hypothesis) chỉ ra giới hạn động lực năng lượng: chỉ $\\approx 10\\%$ năng lượng bậc dưới được cố định sang sinh khối bậc trên kế tiếp."},{"id":"MCQ-PH-109","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh lý Sinh trưởng & Biến thái Côn trùng","q":"Quá trình lột xác và biến thái hoàn toàn ở sâu bướm được kiểm soát bởi sự tương tác cân đối của $2$ hormone chính nào?","opts":["Auxin và Gibberellin.","Ecdysone (gây lột xác) và Hormone trẻ hóa Juvenile (JH: nồng độ cao duy trì trạng thái sâu bướm khi lột xác; giảm thấp thì sâu hóa nhộng rồi hóa bướm).","Estrogen và Testosterone.","Insulin và Adrenalin."],"ans":1,"exp":"Xung Ecdysone kích hoạt lột xác; hàm lượng JH quyết định kết quả lột xác (sâu $\\rightarrow$ sâu lớn khi JH cao, sâu $\\rightarrow$ nhộng khi JH giảm, nhộng $\\rightarrow$ bướm khi JH rất thấp)."},{"id":"MCQ-PH-110","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp & Hb bào thai","q":"Đường cong phân ly $Hb-O_2$ của Hemoglobin bào thai người ($HbF$: $\\alpha_2 \\gamma_2$) nằm dịch sang BÊN TRÁI so với Hemoglobin người trưởng thành ($HbA$: $\\alpha_2 \\beta_2$) mang ý nghĩa thích nghi quan trọng nào?","opts":["$HbF$ có ái lực với $O_2$ thấp hơn nhiều nên nhả hết oxy cho nhau thai mẹ.","$HbF$ chỉ liên kết với $CO_2$ mà không nhận $O_2$.","Máu bào thai có pH thấp bằng $2.0$.","$HbF$ có ái lực với $O_2$ cao hơn $HbA$ ở cùng phân áp oxy, giúp máu thai nhi thu nhận dễ dàng $O_2$ từ máu mẹ xuyên qua nhau thai."],"ans":3,"exp":"Nhờ chuỗi $\\gamma$ gắn $2,3$-BPG kém hơn chuỗi $\\beta$, $HbF$ giữ ái lực $O_2$ cao hơn $HbA$, tạo thuận lợi truyền $O_2$ một chiều từ tuần hoàn mẹ sang thai nhi."},{"id":"MCQ-PH-111","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh thái Thích nghi Thực vật (Cố định Sáng)","q":"Trong quần xã đồng ruộng, khi cấy lúa quá dày thiếu ánh sáng cho các tầng lá dưới gốc, tại sao việc tỉa bớt lá già tầng dưới (bị che râm dưới điểm bù ánh sáng) lại giúp tăng năng suất thu hoạch hạt?","opts":["Vì lá già sản sinh tia phóng xạ ức chế hạt lúa.","Vì các lá bị che râm có cường độ quang hợp nhỏ hơn cường độ hô hấp ($A < R$), tiêu thụ đường ròng (ăn bám cây) thay vì đóng góp chất hữu cơ tích lũy cho bông lúa.","Vì cây chỉ quang hợp được bằng thân chứ không dùng lá.","Vì cắt lá giúp cây chuyển từ thực vật $C_3$ thành $C_4$ ngay lập tức."],"ans":1,"exp":"Lá dưới điểm bù ánh sáng trở thành cơ quan tiêu thụ ('ký sinh sinh lý') lấy sản phẩm quang hợp từ các lá khỏe phía trên."},{"id":"MCQ-PH-112","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa Đường huyết & Nội tiết","q":"Ở bệnh nhân đái tháo đường Type 1 (tuyến tụy bị tự miễn phá hủy tế bào $\\beta$ không sản xuất được Insulin), biểu hiện thường gặp nào xuất hiện trong xét nghiệm máu và nước tiểu?","opts":["Tăng dự trữ glycogen khổng lồ ở cơ và giảm đi tiểu.","Đường huyết tụt xuống dưới $20\\text{ mg/dL}$ liên tục sau bữa ăn.","Áp suất thẩm thấu nước tiểu tụt về bằng $0$.","Đường huyết tăng rất cao, xuất hiện đường glucose trong nước tiểu (vượt ngưỡng tái hấp thu thận $\\approx 180\\text{ mg/dL}$), tăng tiểu tiện (đa niệu thẩm thấu) và dễ nhiễm toan xeton."],"ans":3,"exp":"Thiếu Insulin khiến glucose không vào được tế bào cơ/mỡ để sử dụng, đường máu vượt ngưỡng vận chuyển tối đa ($T_m$) ở ống lượn gần kéo theo nước ra nước tiểu gây đái tháo nhiều và khát nước."},{"id":"MCQ-PH-113","topic":"physiology","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Mô hình Đảo MacArthur - Wilson","q":"Theo thuyết địa lý sinh học đảo của Robert MacArthur và E.O. Wilson, hai hòn đảo mới hình thành có cùng khoảng cách tới đất liền nhưng đảo X có diện tích gấp $10$ lần đảo Y. Ở trạng thái cân bằng số loài trên đảo, dự đoán nào đúng nhất?","opts":["Đảo X không bao giờ có loài nào nhập cư được.","Đảo X có tốc độ tuyệt chủng loài thấp hơn và số loài cân bằng trên đảo lớn hơn đảo Y.","Hai đảo có số loài cân bằng giống hệt nhau bất kể kích thước.","Đảo Y có số loài cân bằng lớn gấp $10$ lần đảo X."],"ans":1,"exp":"Đảo diện tích lớn có nhiều sinh cảnh và quần thể lớn hơn nên tỷ lệ tuyệt chủng thấp hơn $\\Rightarrow$ đường cong cắt nhau ở số loài cân bằng $S^*$ cao hơn; đảo gần đất liền hơn có tỷ lệ nhập cư cao hơn."},{"id":"MCQ-PH-114","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Thận - Độ Thanh thải (Clearance)","q":"Trong lâm sàng đánh giá chức năng thận bằng chất chỉ thị Inulin (được lọc tự do ở cầu thận, hoàn toàn KHÔNG bị tái hấp thu và KHÔNG bị bài tiết thêm tại ống thận), kết quả đo ở một bệnh nhân thu được: nồng độ Inulin huyết tương $P = 0.25\\text{ mg/ml}$, nồng độ Inulin nước tiểu $U = 30\\text{ mg/ml}$, lưu lượng nước tiểu $V = 1.0\\text{ ml/phút}$. Cùng lúc đó chất Y có $P_Y = 0.10\\text{ mg/ml}$ và $U_Y = 6.0\\text{ mg/ml}$. Tốc độ lọc cầu thận ($GFR$) và kết luận về chất Y là:","opts":["$GFR = 120\\text{ ml/phút}$; chất Y không hề được lọc qua cầu thận.","$GFR = 30\\text{ ml/phút}$; chất Y bị giữ hoàn toàn trong huyết tương.","$GFR = 120\\text{ ml/phút}$; chất Y có độ thanh thải $C_Y = 60\\text{ ml/phút} < GFR$ chứng tỏ chất Y đã bị ống thận TÁI HẤP THU thuần ($50\\%$).","$GFR = 60\\text{ ml/phút}$; chất Y được ống thận BÀI TIẾT thêm mạnh mẽ."],"ans":2,"exp":"$GFR = C_{\\text{inulin}} = \\frac{U \\cdot V}{P} = \\frac{30 \\times 1.0}{0.25} = 120\\text{ ml/phút}$. Độ thanh thải chất Y là $C_Y = \\frac{6.0 \\times 1.0}{0.10} = 60\\text{ ml/phút}$. Vì $C_Y < GFR$ (nếu $Y$ lọc tự do), ống thận đã tái hấp thu thuần một nửa lượng Y lọc qua."},{"id":"MCQ-PH-115","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Thận - Huyết tương thận (PAH)","q":"Chất PAH (Para-aminohippuric acid) ở nồng độ thấp được lọc ở cầu thận VÀ được ống lượn gần bài tiết chủ động gần như sạch $100\\%$ ngay trong một lượt qua thận. Nếu đo $P_{\\text{PAH}} = 0.02\\text{ mg/ml}$, $U_{\\text{PAH}} = 6.0\\text{ mg/ml}$, $V = 2.0\\text{ ml/phút}$ và dung tích hồng cầu $Hct = 40\\%$, thì lưu lượng huyết tương thận hiệu dụng ($ERPF$) và lưu lượng máu toàn phần qua thận ($ERBF$) xấp xỉ:","opts":["$ERPF = 600\\text{ ml/phút}$ và $ERBF = 600\\text{ ml/phút}$.","$ERPF = 600\\text{ ml/phút}$ và $ERBF = 1000\\text{ ml/phút}$.","$ERPF = 300\\text{ ml/phút}$ và $ERBF = 500\\text{ ml/phút}$.","$ERPF = 1200\\text{ ml/phút}$ và $ERBF = 1500\\text{ ml/phút}$."],"ans":1,"exp":"$ERPF = C_{\\text{PAH}} = \\frac{6.0 \\times 2.0}{0.02} = 600\\text{ ml/phút}$. Do huyết tương chiếm $1 - Hct = 1 - 0.4 = 0.6$ thể tích máu, suy ra lưu lượng máu qua thận $ERBF = \\frac{600}{0.6} = 1000\\text{ ml/phút}$!"},{"id":"MCQ-PH-116","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Áp suất Lọc Cầu thận thực ($NFP$)","q":"Tại mao mạch cầu thận của người khỏe mạnh, áp suất thủy tĩnh máu mao mạch cầu thận là $P_{GC} = 55\\text{ mmHg}$, áp suất thủy tĩnh bao Bowman chống lại là $P_{BS} = 15\\text{ mmHg}$, và áp suất keo protein huyết tương mao mạch cầu thận là $\\pi_{GC} = 30\\text{ mmHg}$ ($\\pi_{BS} = 0$). Nếu một viên sỏi kẹt niệu quản làm $P_{BS}$ tăng đột ngột lên $30\\text{ mmHg}$, giá trị áp suất lọc thuần ($NFP$) ban đầu và hiện tại thay đổi như thế nào?","opts":["Giảm từ $+10\\text{ mmHg}$ xuống còn $-5\\text{ mmHg}$ (ngừng lọc cầu thận hoàn toàn, nguy cơ vô niệu cấp).","Giảm từ $+40\\text{ mmHg}$ xuống $+10\\text{ mmHg}$.","Không thay đổi, vẫn giữ ở $+10\\text{ mmHg}$.","Tăng từ $+10\\text{ mmHg}$ lên $+25\\text{ mmHg}$."],"ans":0,"exp":"Ban đầu $NFP = P_{GC} - P_{BS} - \\pi_{GC} = 55 - 15 - 30 = +10\\text{ mmHg}$. Khi tắc niệu quản đẩy $P_{BS} = 30\\text{ mmHg}$: $NFP = 55 - 30 - 30 = -5\\text{ mmHg} \\le 0 \\Rightarrow$ ngừng lọc cầu thận."},{"id":"MCQ-PH-117","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điện sinh học Màng & Phương trình Nernst","q":"Sử dụng phương trình Nernst đơn giản hóa ở $37^\\circ\\text{C}$ ($E_{\\text{ion}} = \\frac{61}{z} \\log_{10} \\frac{[\\text{ion}]_{\\text{ngoài}}}{[\\text{ion}]_{\\text{trong}}}$ mV) cho một tế bào thần kinh có $[Ca^{2+}]_{\\text{ngoài}} = 2.0\\text{ mM}$ và $[Ca^{2+}]_{\\text{trong}} = 0.0002\\text{ mM}$ (điện hóa trị $z = +2$). Điện thế cân bằng $E_{Ca}$ của ion canxi qua màng tế bào là:","opts":["$+244\\text{ mV}$.","$-122\\text{ mV}$.","$+122\\text{ mV}$.","$+61\\text{ mV}$."],"ans":2,"exp":"Thay $z = +2$ và tỷ số $\\frac{2.0}{0.0002} = 10^4$: $E_{Ca} = \\frac{61}{2} \\log_{10}(10^4) = 30.5 \\times 4 = +122\\text{ mV}$. Vì bên ngoài dương hơn nên mở kênh $Ca^{2+}$ kéo mạnh dòng $Ca^{2+}$ vào trong bào tương."},{"id":"MCQ-PH-118","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Độc chất học Xinap & Kênh Ion","q":"Khi nhỏ độc tố cá nóc <strong>Tetrodotoxin (TTX)</strong> vào dung dịch ngâm sợi trục thần kinh khổng lồ mực ống và đồng thời kích thích đủ ngưỡng, kết quả ghi điện thế hoạt động nào sẽ quan sát được?","opts":["Tốc độ dẫn truyền tăng vọt gấp $5$ lần.","Điện thế nghỉ lập tức chuyển thành $0\\text{ mV}$ dù chưa kích thích.","Mất hoàn toàn pha khử cực đảo cực ($+30\\text{ mV}$) của điện thế hoạt động vì TTX phong bế đặc hiệu kênh $Na^+$ cổng điện thế, nhưng điện thế nghỉ ($\\approx -70\\text{ mV}$) gần như không bị ảnh hưởng.","Điện thế vọt lên $+30\\text{ mV}$ rồi giữ yên mãi mãi không tái phân cực được."],"ans":2,"exp":"TTX khóa chọn lọc kênh $Na^+$ cổng điện thế (tránh pha khử cực bùng nổ của điện thế hoạt động), khác với TEA vốn phong bế kênh $K^+$ làm mất/chậm pha tái phân cực."},{"id":"MCQ-PH-119","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Độc chất học Xinap - Curare & Botulinum","q":"So sánh cơ chế tác động gây liệt cơ của hai loại độc tố sinh học nổi tiếng: <strong>Độc tố Botulinum</strong> (từ vi khuẩn *Clostridium botulinum*) và <strong>Curare</strong> (chất độc tẩm mũi tên Nam Mỹ). Khẳng định nào sau đây là chính xác?","opts":["Botulinum cắt đứt protein SNARE ở chùy xinap ngăn GIẢI PHÓNG Acetylcholine vào khe xinap; còn Curare gắn cạnh tranh vào thụ thể $nAChR$ trên màng sau xinap ngăn Acetylcholine mở kênh.","Cả hai chất đều kích thích tiết Acetylcholine ồ ạt gây co cứng toàn thân.","Cả hai chất đều chỉ tác động vào bao myelin ở hành não.","Botulinum ức chế Acetylcholinesterase tại khe xinap, còn Curare kích thích thụ thể $GABA$ tại não."],"ans":0,"exp":"Đều gây liệt mềm cơ vân (ngừng hô hấp) nhưng ở 2 vị trí đối diện qua khe xinap: Botulinum (tiền xinap — cắt SNAP-25/Synaptobrevin) và d-Tubocurarine/Curare (hậu xinap — đối kháng cạnh tranh nAChR)."},{"id":"MCQ-PH-120","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thí nghiệm Quang hợp Đồng vị $^{14}C$ (Calvin-Benson)","q":"Trong thí nghiệm chiếu sáng tảo đơn bào *Chlorella* sục khí $^{14}CO_2$ đang quang hợp ổn định, nếu nhà khoa học đột ngột <strong>TẮT ĐÈN</strong> (ngưng cung cấp ATP và NADPH từ pha sáng) trong khi vẫn duy trì nguồn $CO_2$, sự biến đổi nồng độ tương đối giữa hai chất <strong>RuBP</strong> ($C_5$) và <strong>3-PGA</strong> ($C_3$) trong những giây đầu tiên là:","opts":["Nồng độ RuBP TĂNG vọt còn nồng độ 3-PGA GIẢM về $0$.","Cả hai chất hoàn toàn giữ nguyên không thay đổi.","Nồng độ 3-PGA TĂNG vọt còn nồng độ RuBP GIẢM mạnh về $0$.","Cả hai chất đều tăng vọt cùng lúc gấp $10$ lần."],"ans":2,"exp":"Khi tắt đèn (mất ATP, NADPH), bước cố định $CO_2$ ($\\text{RuBP} + CO_2 \\rightarrow 2\\text{ PGA}$) không cần ATP/NADPH vẫn tiếp tục chạy tiêu thụ sạch RuBP để tạo PGA; còn bước khử PGA $\\rightarrow$ G3P và tái sinh RuBP (cần ATP/NADPH) bị dừng lại $\\Rightarrow$ PGA tích tụ tăng, RuBP cạn giảm."},{"id":"MCQ-PH-121","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thí nghiệm Quang hợp Đồng vị $^{14}C$ (Ngắt $CO_2$)","q":"Ngược lại với tình huống trên, nếu đang chiếu sáng ổn định cho tảo *Chlorella* mà đột ngột <strong>NGẮT NGUỒN $CO_2$</strong> (giảm nồng độ $CO_2$ xuống gần $0$) trong khi vẫn chiếu sáng mạnh bình thường, biến động hàm lượng RuBP và 3-PGA trong những giây đầu tiên là:","opts":["Cả hai chất đều giảm đồng loạt.","Nồng độ RuBP TĂNG mạnh còn nồng độ 3-PGA GIẢM nhanh.","Nồng độ 3-PGA TĂNG mạnh còn nồng độ RuBP GIẢM nhanh.","Chỉ tạo ra OAA mà không tạo G3P."],"ans":1,"exp":"Khi thiếu $CO_2$, phản ứng $CO_2 + \\text{RuBP} \\rightarrow 2\\text{ PGA}$ bị chặn lại khiến RuBP không bị tiêu thụ mà còn được tái sinh liên tục từ lượng PGA còn lại nhờ ATP, NADPH pha sáng $\\Rightarrow$ RuBP tăng vọt, PGA tụt giảm."},{"id":"MCQ-PH-122","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Định lượng ATP & NADPH trong Quang hợp C3 vs C4","q":"Để tổng hợp được <strong>$2$ phân tử đường Saccarôzơ</strong> ($C_{12}H_{22}O_{11}$) trong tế bào thực vật $C_4$ (giả sử chi phí mỗi phân tử $CO_2$ cố định ở cây $C_4$ cần $5\\text{ ATP}$ và $2\\text{ NADPH}$, bỏ qua hô hấp sáng), tổng số phân tử ATP và NADPH cần tiêu tốn ở pha tối xấp xỉ là bao nhiêu?","opts":["$72\\text{ ATP}$ và $48\\text{ NADPH}$.","$120\\text{ ATP}$ và $48\\text{ NADPH}$.","$60\\text{ ATP}$ và $24\\text{ NADPH}$.","$90\\text{ ATP}$ và $36\\text{ NADPH}$."],"ans":1,"exp":"$1$ phân tử Saccarôzơ có $12$ nguyên tử cacbon $\\Rightarrow$ $2$ Saccarôzơ cần cố định $24$ phân tử $CO_2$. Trong thực vật $C_4$, mỗi $CO_2$ cần $2\\text{ ATP}$ tái tạo PEP cộng $3\\text{ ATP}$ chu trình Calvin $= 5\\text{ ATP}$ và $2\\text{ NADPH}$. Vậy tổng cộng: $24 \\times 5 = 120\\text{ ATP}$ và $24 \\times 2 = 48\\text{ NADPH}$."},{"id":"MCQ-PH-123","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Chim & Thích nghi Độ cao lớn","q":"Chim ngỗng đầu vằn (*Anser indicus*) bay vượt đỉnh Himalaya ở độ cao $\\approx 9000\\text{ m}$ (phân áp $O_2$ chỉ còn khoảng $1/3$ mực nước biển) mà không bị ngất xỉu hay phù não như người thường. Tổ hợp thích nghi sinh lý đặc hiệu nào giúp chúng vượt trội ở môi trường giảm oxy cực độ?","opts":["Hemoglobin có ái lực với $O_2$ cực cao (đột biến điểm thay đổi cấu trúc $\\alpha$-globin), phổi luồng $1$ chiều có diện tích trao đổi khí lớn, mật độ mao mạch và ty thể trong cơ bay dày đặc.","Hồng cầu chim không nhân có kích thước to gấp $5$ lần tế bào gan.","Chim chuyển hoàn toàn sang lên men rượu trong toàn bộ đường bay qua dãy núi.","Tim chim ngừng đập hoàn toàn khi bay trên $5000\\text{ m}$."],"ans":0,"exp":"Ngỗng đầu vằn sở hữu tổ hợp tiến hóa đa cấp: tăng thông khí chịu được kiềm hô hấp không gây co mạch não, $Hb$ dịch trái ái lực cao, tăng sinh mao mạch cơ bay và chuyển dịch ty thể sát màng sợi cơ."},{"id":"MCQ-PH-124","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bệnh lý Nội tiết (Cushing vs Addison vs Graves)","q":"Một bệnh nhân có kết quả xét nghiệm: nồng độ Cortisol máu tăng rất cao, nhưng nồng độ $ACTH$ tuyến yên và $CRH$ vùng dưới đồi đều bị ức chế giảm xuống gần bằng $0$, kèm triệu chứng mặt tròn đỏ, tích mỡ thân mình, tăng đường huyết và huyết áp cao. Chẩn đoán vị trí tổn thương hợp lý nhất là:","opts":["Khối u lành tính hoặc ác tính tự chủ ở vỏ tuyến thượng thận (tăng tiết Cortisol nguyên phát gây ức chế ngược âm tính lên dưới đồi và tuyến yên — Hội chứng Cushing nguyên phát).","U tuyến yên tăng tiết $ACTH$ (Bệnh Cushing thứ phát).","Thiếu hụt hormone $ADH$ của thùy sau tuyến yên.","Suy phá hủy toàn bộ vỏ tuyến thượng thận (Bệnh Addison)."],"ans":0,"exp":"Nếu u tuyến yên gây bệnh Cushing, $ACTH$ phải cao cùng Cortisol. Ở đây Cortisol cao nhưng $ACTH, CRH$ đều tụt thấp $\\rightarrow$ tăng tiết nguyên phát tại khối u vỏ thượng thận ức chế ngược trục trên."},{"id":"MCQ-PH-125","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Rối loạn Thăng bằng Nước (Đái tháo nhạt vs SIADH)","q":"Phân biệt hai rối loạn nội tiết liên quan đến hormone $ADH$: Bệnh nhân P bị chấn thương đầu khiến tuyến yên không tiết được $ADH$ (Đái tháo nhạt trung ương); Bệnh nhân Q bị ung thư phổi tế bào nhỏ tiết ra lượng $ADH$ dư thừa (Hội chứng SIADH). Biện pháp xét nghiệm nào phân biệt chính xác ngay trạng thái máu và nước tiểu của P và Q?","opts":["Bệnh nhân P tiểu rất nhiều nước tiểu loãng (áp suất thẩm thấu niệu thấp), natri máu tăng cao; Bệnh nhân Q tiểu ít nước tiểu cô đặc, bị giữ nước dẫn tới hạ natri máu nặng.","Bệnh nhân P có đường huyết và đường niệu rất cao kèm toan xeton.","Cả P và Q đều có natri máu tăng vọt và vô niệu hoàn toàn.","Bệnh nhân Q bài tiết trên $15$ lít nước tiểu trong vắt mỗi ngày."],"ans":0,"exp":"Thiếu $ADH$ (Đái tháo nhạt) $\\rightarrow$ thận không tái hấp thu nước ở ống góp $\\rightarrow$ mất nước tự do gây tiểu loãng và tăng natri máu; thừa $ADH$ (SIADH) $\\rightarrow$ giữ nước quá mức gây pha loãng natri máu và cô đặc nước tiểu."},{"id":"MCQ-PH-126","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điện tâm đồ (ECG) & Block Nhĩ-Thất","q":"Khi đọc điện tâm đồ (ECG) của một bệnh nhân cho thấy: các sóng $P$ xuất hiện đều đặn với tần số $80\\text{ nhịp/phút}$, các phức bộ $QRS$ cũng đều đặn nhưng hoàn toàn ĐỘC LẬP với sóng $P$ và chỉ có tần số chậm $35\\text{ nhịp/phút}$ (sóng $P$ rơi lung tung không liên hệ cố định trước $QRS$). Chẩn đoán rối loạn dẫn truyền tim này là:","opts":["Block nhĩ-thất độ I chỉ kéo dài khoảng $PR > 0.20\\text{ s}$.","Block xoang-nhĩ hoàn toàn không có sóng $P$.","Nhịp xoang bình thường ở vận động viên chuyên nghiệp.","Block nhĩ-thất độ III (Block nhĩ-thất hoàn toàn): xung từ nút xoang nhĩ chỉ khử cực nhĩ ($P$) bị chặn sạch tại nút nhĩ-thất; thất tự phát nhịp thoát chậm ($35\\text{ lần/phút}$) từ bó His / mạng Purkinje."],"ans":3,"exp":"Sự phân ly nhĩ-thất hoàn toàn ($P$ và $QRS$ chạy theo hai nhịp độc lập, $QRS$ chậm đặc trưng $30-40$ nhịp của ổ phát nhịp thất) là dấu hiệu kinh điển của Block nhĩ-thất độ III."},{"id":"MCQ-PH-127","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Đông vật - Hệ Đệm & Toan chuyển hóa","q":"Một bệnh nhân bị tiêu chảy cấp mất nhiều dịch ruột giàu $HCO_3^-$ dẫn đến <strong>nhiễm toan chuyển hóa</strong> (pH máu giảm xuống $7.25$, nồng độ $[HCO_3^-]$ giảm mạnh). Cơ quan nào sẽ đáp ứng bù trừ nhanh nhất trong vòng vài phút đầu tiên và biểu hiện hô hấp nào xuất hiện?","opts":["Gan chuyển hóa $O_2$ thành axit lactic để tăng pH.","Trung khu hô hấp bị kích thích bởi $H^+$ làm tăng tần số và biên độ thở (thở nhanh sâu - kiểu thở Kussmaul) để tăng thải $CO_2$, giảm $pCO_2$ kéo tỷ số $[HCO_3^-]/pCO_2$ lên gần bình thường.","Bệnh nhân nín thở hoàn toàn để giữ thật nhiều $CO_2$ trong máu.","Thận tăng bài tiết toàn bộ $HCO_3^-$ ra ngoài trong vòng $30$ giây."],"ans":1,"exp":"Hệ hô hấp bù trừ rất nhanh cho rối loạn chuyển hóa: nhiễm toan kích thích thụ thể hóa học ngoại biên (xoang cảnh, cung động mạch chủ) gây tăng thông khí tống $CO_2$ giảm tính axit máu."},{"id":"MCQ-PH-128","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quang chu kỳ & Ghép nối Thực vật","q":"Ở một thí nghiệm ghép nối $2$ cây thuộc cùng một loài cây ngày NGẮN (chỉ ra hoa khi đêm dài $\\ge 10$ giờ): cây A được đặt trong chế độ $8\\text{ h}$ sáng / $16\\text{ h}$ tối (cảm ứng), cây B đặt trong chế độ $16\\text{ h}$ sáng / $8\\text{ h}$ tối (không cảm ứng). Nếu cắt bỏ <strong>TẤT CẢ CÁC LÁ</strong> trên cây A trước khi ghép nối dẫn truyền qua thân sang cây B (cây B còn nguyên lá), hiện tượng nào xảy ra?","opts":["Chỉ cây A ra hoa, còn cây B chết héo.","Cả hai cây A và B ĐỀU KHÔNG RA HOA (vì bộ phận tiếp nhận quang chu kỳ và tổng hợp chất kích thích ra hoa Florigen là LÁ; cây A không còn lá trong tối dài còn lá cây B lại ở ngày dài ức chế).","Cây B tự động chuyển thành cây ngày dài và ra hoa.","Cả cây A và cây B đều nở hoa rực rỡ vì thân cây A tự cảm ứng."],"ans":1,"exp":"Thực nghiệm kinh điển Chailakhyan: lá là cơ quan tiếp nhận quang chu kỳ tổng hợp tín hiệu protein FT (Florigen) vận chuyển theo mạch rây đến đỉnh sinh trưởng; không có lá ở chế độ cảm ứng thì không có Florigen."},{"id":"MCQ-PH-129","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bảng sống & Tăng trưởng Quần thể ($R_0, T$)","q":"Nghiên cứu một quần thể côn trùng sinh sản theo lứa với bảng sống chuẩn hóa theo các lớp tuổi $x$ (năm): tuổi $0$ ($l_0 = 1.0, m_0 = 0$), tuổi $1$ ($l_1 = 0.5, m_1 = 2.0$), tuổi $2$ ($l_2 = 0.2, m_2 = 3.0$), tuổi $3$ ($l_3 = 0.0, m_3 = 0$). Tỷ lệ sinh sản thực ($R_0 = \\sum l_x m_x$) và thời gian thế hệ trung bình ($T = \\frac{\\sum x l_x m_x}{R_0}$) của quần thể này lần lượt là:","opts":["$R_0 = 1.6$ và $T = 1.375\\text{ năm}$.","$R_0 = 1.0$ và $T = 2.000\\text{ năm}$.","$R_0 = 5.0$ và $T = 1.500\\text{ năm}$.","$R_0 = 0.8$ và $T = 1.250\\text{ năm}$."],"ans":0,"exp":"$R_0 = 1.0(0) + 0.5(2.0) + 0.2(3.0) = 1.0 + 0.6 = 1.6 > 1$ (quần thể đang tăng trưởng). $\\sum x l_x m_x = 0(0) + 1(1.0) + 2(0.6) = 2.2 \\Rightarrow T = \\frac{2.2}{1.6} = 1.375\\text{ năm}$."},{"id":"MCQ-PH-130","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chỉ số Đa dạng Sinh học Shannon-Wiener ($H'$)","q":"Khảo sát một quần xã thực vật gồm $4$ loài có tỷ lệ cá thể $p_i$ bằng nhau hoàn toàn ($p_1 = p_2 = p_3 = p_4 = 0.25$). Sử dụng công thức Shannon-Wiener cơ số $2$: $H' = -\\sum_{i=1}^S p_i \\log_2 p_i$, giá trị chỉ số đa dạng $H'$ đạt mức cực đại là bao nhiêu bit?","opts":["$H' = 0.25\\text{ bit}$.","$H' = 2.0\\text{ bit}$.","$H' = 4.0\\text{ bit}$.","$H' = 1.0\\text{ bit}$."],"ans":1,"exp":"Vì $4$ loài phân bố đồng đều tuyệt đối: $H' = -4 \\times [0.25 \\times \\log_2(0.25)] = -1 \\times (-2) = 2.0$ bit (bằng $\\log_2 S = \\log_2 4$). Nếu độ đồng đều giảm xuống, $H'$ sẽ nhỏ hơn $2.0$."},{"id":"MCQ-PH-131","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Truyền Năng lượng qua Hệ Sinh thái","q":"Trong một hệ sinh thái đồng cỏ, sinh vật sản xuất (cỏ) nhận tổng bức xạ mặt trời $2 \\times 10^6\\text{ kcal/m}^2\\text{/năm}$, nhưng chỉ chuyển hóa được $1.0\\%$ thành sản lượng sơ cấp tinh ($NPP$). Hiệu suất chuyển hóa năng lượng giữa các bậc kế tiếp đều là $10\\%$, riêng từ sinh vật tiêu thụ bậc $2$ sang bậc $3$ là $15\\%$. Năng lượng tích lũy ở sinh vật tiêu thụ BẬC $3$ (bậc dinh dưỡng cấp $4$) là bao nhiêu?","opts":["$300.0\\text{ kcal/m}^2\\text{/năm}$.","$200.0\\text{ kcal/m}^2\\text{/năm}$.","$20.0\\text{ kcal/m}^2\\text{/năm}$.","$30.0\\text{ kcal/m}^2\\text{/năm}$."],"ans":3,"exp":"SVSX ($NPP$) $= 1\\% \\times 2 \\times 10^6 = 2 \\times 10^4\\text{ kcal}$. SVTT bậc $1 = 10\\% \\times 2 \\times 10^4 = 2000\\text{ kcal}$. SVTT bậc $2 = 10\\% \\times 2000 = 200\\text{ kcal}$. SVTT bậc $3 = 15\\% \\times 200 = 30.0\\text{ kcal/m}^2\\text{/năm}$."},{"id":"MCQ-PH-132","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Chuyển hóa Dinh dưỡng thực vật","q":"Tại sao khi bón phân có chứa nguyên tố đồng ($Cu$) hoặc kẽm ($Zn$) quá dư thừa trong đất chua (pH thấp) có thể gây triệu chứng thiếu sắt ($Fe$) hoặc thiếu magie ($Mg$) trên lá non dù lượng $Fe, Mg$ trong đất vẫn đủ?","opts":["Đồng và kẽm biến đổi nguyên tử $Fe$ thành đồng vị nitơ bay hơi mất.","Rễ cây ngừng tạo ATP ngay lập tức khi có mặt mọi ion kim loại.","$Mg$ chỉ được hấp thụ trực tiếp từ không khí qua khí khổng.","Hiện tượng đối kháng ion trong hấp thụ khoáng (các cation kim loại hóa trị $2$ cạnh tranh kênh vận chuyển màng và vị trí liên kết enzyme/chelator tại rễ) cùng sự mất cân bằng pH cản trở hấp thụ chọn lọc."],"ans":3,"exp":"Sự cân bằng tỷ lệ ion đất quyết định hiệu quả hấp thụ chọn lọc: dư thừa $Zn^{2+}, Mn^{2+}, Cu^{2+}$ cạnh tranh protein mang và điểm gắn với $Fe^{2+}$ gây vàng lá thiếu sắt thứ phát."},{"id":"MCQ-PH-133","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Quang hợp - Định luật Blackman","q":"Ở cường độ ánh sáng thấp (vùng giới hạn bởi ánh sáng), khi giữ nguyên ánh sáng yếu và tăng dần nồng độ $CO_2$ từ $0.03\\%$ lên $0.1\\%$, tốc độ quang hợp của lá gần như KHÔNG tăng thêm; ngược lại nếu tăng ánh sáng lên mạnh hơn rồi mới tăng $CO_2$ thì quang hợp tăng vọt. Hiện tượng này minh họa cho nguyên lý nào?","opts":["Hiện tượng cộng hưởng lượng tử giữa các sắc tố phụ.","Quy luật ưu thế dị hợp tử.","Định luật cân bằng Hardy-Weinberg.","Nguyên lý nhân tố giới hạn (Blackman / Liebig): tốc độ của một quá trình phụ thuộc nhiều yếu tố được quyết định bởi yếu tố có mức thấp nhất đang ở dưới ngưỡng tối ưu (ở đây là thiếu ATP, NADPH từ pha sáng)."],"ans":3,"exp":"Khi ánh sáng yếu, tốc độ pha sáng tạo ATP, NADPH trở thành nút thắt giới hạn (limiting factor) nên tăng dư thừa cơ chất $CO_2$ cho pha tối cũng không thể đẩy nhanh chu trình Calvin."},{"id":"MCQ-PH-134","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chu kỳ Tim & Tiếng Tim bệnh lý","q":"Ở một bệnh nhân được chẩn đoán hở van hai lá (van nhĩ-thất trái không đóng kín hoàn toàn), tiếng thổi bất thường nghe rõ nhất vào pha nào của chu kỳ tim và hậu quả huyết động trực tiếp lên buồng tim nào xảy ra sớm nhất?","opts":["Máu từ động mạch phổi chảy thẳng vào cung động mạch chủ.","Không tạo ra bất kỳ tiếng thổi nào vì van không tham gia ngăn dòng chảy.","Nghe tiếng thổi thì tâm nhĩ co; gây vỡ tâm thất phải ngay lập tức.","Nghe tiếng thổi toàn thì TÂM THU thất (khi tâm thất trái co tống máu, một phần máu phụt ngược qua van hở về tâm nhĩ trái); gây dãn và tăng áp lực tâm nhĩ trái dẫn tới ứ huyết phổi."],"ans":3,"exp":"Bình thường khi tâm thất bắt đầu co (đóng van nhĩ-thất gây tiếng T1), van hai lá phải đóng kín. Nếu hở van hai lá, áp suất thất trái cao đẩy dòng máu xoáy phụt ngược về nhĩ trái suốt thì tâm thu tạo tiếng thổi tâm thu."},{"id":"MCQ-PH-135","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp & Định luật Laplace ở Phế nang","q":"Trẻ sinh non trước tuần thai thứ $28$ thường mắc hội chứng suy hô hấp sơ sinh (NRDS) gây xẹp phế nang nghiêm trọng sau mỗi nhịp thở ra. Nguyên nhân sinh lý trực tiếp theo định luật Laplace ($P = \\frac{2T}{r}$) là do thiếu tế bào biểu mô phế nang loại II tiết chất nào?","opts":["Thiếu chất hoạt diện phổi (Surfactant — chủ yếu là phospholipid dipalmitoylphosphatidylcholine), làm sức căng bề mặt $T$ trong dịch lót phế nang rất cao khiến các phế nang nhỏ (bán kính $r$ nhỏ) bị áp lực co xẹp vào phế nang lớn.","Thiếu enzyme pepsin tiêu hóa dịch phổi.","Thiếu cơ trơn ở thành động mạch chủ.","Thiếu hemoglobin chuỗi $\\beta$ trong huyết tương."],"ans":0,"exp":"Surfactant xen vào lớp phân tử nước làm giảm mạnh sức căng bề mặt $T$ (giảm càng nhiều khi bán kính $r$ càng nhỏ), cân bằng áp lực $P=2T/r$ giúp phế nang nhỏ không bị xẹp."},{"id":"MCQ-PH-136","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Định luật Poiseuille & Kháng lực Mạch máu","q":"Theo định luật Hagen-Poiseuille, sức cản dòng máu ($R$) trong một tiểu động mạch phụ thuộc theo lũy thừa bậc mấy với bán kính lòng mạch $r$ ($R = \\frac{8 \\eta L}{\\pi r^4}$)? Nếu tiểu động mạch bị co thắt khiến bán kính giảm đi một nửa ($r_2 = 0.5 r_1$, giữ nguyên $\\Delta P$), lưu lượng máu ($Q = \\Delta P / R$) qua mạch đó sẽ giảm bao nhiêu lần?","opts":["Sức cản tỉ lệ nghịch $r^4$; bán kính giảm $2$ lần làm sức cản tăng $16$ lần và lưu lượng máu giảm $16$ lần.","Sức cản tăng $4$ lần và lưu lượng giảm $4$ lần.","Sức cản tăng $2$ lần và lưu lượng giảm $2$ lần.","Sức cản giảm $16$ lần và lưu lượng tăng $16$ lần."],"ans":0,"exp":"Vì lưu lượng $Q \\propto r^4$, chỉ cần thay đổi nhẹ bán kính tiểu động mạch cũng kiểm soát cực mạnh sự phân phối máu tới các cơ quan ($0.5^4 = 1/16$)."},{"id":"MCQ-PH-137","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hệ Thần kinh - Tính toán Khớp nối Xinap","q":"Xét một nơron vận động đồng thời nhận tín hiệu từ $3$ tận cùng xinap: Xinap $1$ là xinap kích thích gây điện thế sau xinap kích thích $+8\\text{ mV}$; Xinap $2$ là xinap kích thích gây $+10\\text{ mV}$; Xinap $3$ là xinap ức chế gây $-7\\text{ mV}$ ($IPSP$). Biết điện thế nghỉ của nơron là $-70\\text{ mV}$ và ngưỡng phát sinh điện thế hoạt động tại gò sợi trục là $-55\\text{ mV}$. Khi cả $3$ xinap hoạt động đồng thời (cộng gộp không gian), điều gì xảy ra?","opts":["Xinap ức chế luôn bị loại trừ hoàn toàn trước xinap kích thích.","Điện thế màng bị đẩy tụt xuống $-95\\text{ mV}$.","Điện thế màng đạt $-52\\text{ mV} > -55\\text{ mV}$, phát sinh ngay $3$ điện thế hoạt động.","Điện thế màng đạt $-70 + 8 + 10 - 7 = -59\\text{ mV}$ (chưa đạt ngưỡng $-55\\text{ mV}$), nên KHÔNG phát sinh điện thế hoạt động."],"ans":3,"exp":"Cộng gộp không gian: $\\Delta V = (+8) + (+10) + (-7) = +11\\text{ mV} \\Rightarrow V_m = -70 + 11 = -59\\text{ mV}$. Vì $-59\\text{ mV}$ còn âm hơn ngưỡng $-55\\text{ mV}$ nên kênh $Na^+$ không mở bùng nổ."},{"id":"MCQ-PH-138","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quá trình Tiêu hóa Lipid & Nhũ tương hóa","q":"Một bệnh nhân bị cắt túi mật hoặc tắc hoàn toàn ống mật chủ dẫn xuống tá tràng sẽ gặp khó khăn lớn nhất trong việc tiêu hóa và hấp thu nhóm chất dinh dưỡng nào, biểu hiện đặc trưng là gì?","opts":["Axit amin; do dịch mật chứa pepsin thủy phân protein.","Tinh bột và đường đơn; do dịch mật chứa phần lớn enzyme amilaza.","Lipid (chất béo); do thiếu muối mật nhũ tương hóa các giọt mỡ lớn thành hạt vi nhũ tương và không tạo được hạt mixen hấp thu vitamin tan trong dầu (A, D, E, K), dẫn tới phân nhạt màu và có váng mỡ.","Muối khoáng $NaCl$; do mật trực tiếp vận chuyển natri."],"ans":2,"exp":"Dịch mật không chứa enzyme tiêu hóa, nhưng muối mật có bản chất lưỡng cực giúp nhũ tương hóa tăng diện tích tiếp xúc cho Lipase tụy hoạt động và tạo hạt mixen đưa sản phẩm lipid vào tế bào ruột."},{"id":"MCQ-PH-139","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh thái Tương tác Cạnh tranh (Mô hình Lotka-Volterra)","q":"Trong phương trình cạnh tranh Lotka-Volterra của $2$ loài có sức chứa $K_1, K_2$ và hệ số cạnh tranh $\\alpha$ (tác động loài $2$ lên loài $1$), $\\beta$ (tác động loài $1$ lên loài $2$): $\\frac{dN_1}{dt} = r_1 N_1 \\frac{K_1 - N_1 - \\alpha N_2}{K_1}$. Điều kiện cần và đủ để HAI LOÀI CÓ THỂ CÙNG TỒN TẠI ỔN ĐỊNH lâu dài (Coexistence) trong hệ sinh thái là:","opts":["Tốc độ sinh sản $r_1$ phải gấp $100$ lần $r_2$.","Cạnh tranh khác loài luôn lớn gấp $10$ lần cạnh tranh cùng loài.","Cả hai loài có $K_1 = K_2$ và $\\alpha = \\beta = 2$.","Cạnh tranh NỘI LOÀI mạnh hơn cạnh tranh khác loài đối với cả hai loài: $K_1 < \\frac{K_2}{\\beta}$ và $K_2 < \\frac{K_1}{\\alpha}$ (tức $\\alpha < \\frac{K_1}{K_2}$ và $\\beta < \\frac{K_2}{K_1}$)."],"ans":3,"exp":"Khi mỗi loài tự kìm hãm mật độ bản thân (cạnh tranh cùng loài) mạnh hơn khả năng ức chế đối thủ ($\\alpha N_2 < K_1$ tại $N_2=K_2$ và $\\beta N_1 < K_2$ tại $N_1=K_1$), hai đường đồng mức cắt nhau ở điểm cân bằng ổn định nội tại."},{"id":"MCQ-PH-140","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Thực vật - Thử nghiệm Nhiệt độ & Quang hợp","q":"Đặt hai cây: cây lúa ($C_3$) và cây ngô ($C_4$) ở cùng cường độ ánh sáng cao và nồng độ $CO_2$ bình thường rồi tăng nhiệt độ môi trường từ $25^\\circ\\text{C}$ lên $38^\\circ\\text{C}$. Giải thích chính xác tại sao quang hợp của cây lúa sụt giảm rõ rệt hơn cây ngô ở $38^\\circ\\text{C}$?","opts":["Ở nhiệt độ cao, độ hòa tan của $CO_2$ giảm nhanh hơn $O_2$ trong dịch lục lạp và ái lực oxyase của RuBisCO tăng lên thúc đẩy hô hấp sáng mạnh ở cây $C_3$, trong khi cây $C_4$ có bơm $CO_2$ bảo vệ RuBisCO trong bao bó mạch.","Cây ngô không sử dụng enzyme RuBisCO trong chu trình Calvin.","Ở $38^\\circ\\text{C}$, cây lúa mở rộng khí khổng tối đa nhưng mất toàn bộ mạch gỗ.","Diệp lục của cây lúa bị phân hủy thành carotenoid ngay trên $30^\\circ\\text{C}$."],"ans":0,"exp":"Nhiệt độ cao làm giảm tỉ lệ $[CO_2]/[O_2]$ hòa tan và thay đổi động học RuBisCO theo hướng tăng gắn $O_2$ (quang hô hấp). Cây $C_4$ tốn thêm ATP cô đặc $CO_2$ nên ưu thế vượt trội ở vùng nhiệt độ cao, nắng mạnh."},{"id":"MCQ-PH-141","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Máu & Ngộ độc Khí CO","q":"Vì sao hít phải khí Cacbon monoxit ($CO$) ở nồng độ rất thấp cũng nhanh chóng gây tử vong vì ngạt tế bào và làm máu tĩnh mạch có màu đỏ anh đào rực rỡ bất thường?","opts":["$CO$ có ái lực với Hemoglobin cao gấp $\\approx 210-250$ lần $O_2$, chiếm chỗ gắn $O_2$ tạo Carboxyhemoglobin đỏ tươi, ĐỒNG THỜI làm lệch đường cong phân ly $Hb-O_2$ còn lại sang TRÁI khiến $Hb$ không nhả được $O_2$ cho mô.","$CO$ tiêu hủy tủy sống khiến tim không còn nhận xung thần kinh giao cảm.","$CO$ làm dịch chuyển đường cong phân ly $Hb-O_2$ sang PHẢI mạnh nên mất $O_2$ qua da.","$CO$ kết hợp với nước biến toàn bộ hồng cầu thành bọt khí nitơ."],"ans":0,"exp":"$CO$ gây tác động kép chết người: chiếm mất vị trí gắn $O_2$ trên $Hb$ và khóa chặt cấu hình dạng R của các tiểu phần $Hb$ còn lại (dịch đường cong sang trái) làm mô không nhận được $O_2$ dù hồng cầu vẫn đỏ rực."},{"id":"MCQ-PH-142","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh thái Thực vật & Cháy rừng Thích nghi","q":"Ở hệ sinh thái rừng thông Chaparral (vùng Địa Trung Hải hay California), một số loài thông có nón quả đóng kín bằng nhựa cứng suốt nhiều năm, chỉ bung mở phát tán hạt khi gặp nhiệt độ cao từ các vụ cháy rừng tự nhiên định kỳ (Serotiny). Hiện tượng này phản ánh:","opts":["Sự phá hủy hoàn toàn hệ sinh thái do mọi hạt giống đều hóa tro.","Sự tiến hóa thích nghi đồng bộ của quần thể thực vật với nhân tố sinh thái xáo trộn định kỳ (lửa cháy rừng), giúp hạt nảy mầm trên nền đất tro giàu khoáng và ít cạnh tranh.","Ảnh hưởng trực tiếp của đột biến phóng xạ gây ra ở nhựa cây.","Quá trình diễn thế nguyên sinh bắt đầu từ đá trần không có sinh vật."],"ans":1,"exp":"Cháy tự nhiên vừa cung cấp xung nhiệt mở nón quả vừa dọn sạch tầng tán cạnh tranh và trả khoáng vào đất để cây non tái sinh mạnh."},{"id":"MCQ-PH-143","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Động vật - Hệ Tuần hoàn Mạch Vành","q":"Khác với hầu hết các cơ quan khác nhận máu nuôi chủ yếu trong thì TÂM THU (khi tim bóp đẩy máu ra), cơ tim (đặc biệt thành cơ dày tâm thất trái) nhận tới $70-80\\%$ lưu lượng máu nuôi qua động mạch vành chủ yếu vào pha nào của chu kỳ tim và tại sao?","opts":["Chỉ trong $0.05\\text{ s}$ khi van nhĩ-thất vừa mở.","Thì co đẳng tích của tâm thất trái vì áp lực thành cơ tim khi đó bằng $0$.","Mạch vành lấy máu trực tiếp từ tâm nhĩ phải chứ không từ động mạch chủ.","Thì TÂM TRƯƠNG (khi cơ tâm thất dãn nghỉ); vì khi tâm thất co mạnh thì áp suất nội thành cơ tim ép xẹp các nhánh mạch vành xuyên thành cơ tim trái, chỉ khi tim dãn áp suất thành cơ tụt xuống mới cho máu động mạch chủ tràn qua van tổ chim vào mạch vành."],"ans":3,"exp":"Do đó, khi nhịp tim tăng quá nhanh (rút ngắn mạnh thời gian tâm trương hơn thời gian tâm thu), thời gian tưới máu cơ tim và đổ đầy thất giảm mạnh, dễ gây thiếu máu cục bộ cơ tim ở bệnh nhân hẹp mạch vành."},{"id":"MCQ-PH-144","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cơ chế Miễn dịch - Quá trình Opsonin hóa","q":"Trong đáp ứng miễn dịch chống vi khuẩn có vỏ polysaccharide trơn trượt khó bị đại thực bào nuốt, các kháng thể IgG và mảnh bổ thể $C3b$ bao phủ quanh bề mặt vi khuẩn đóng vai trò gì?","opts":["Bảo vệ vi khuẩn khỏi bị các tế bào NK tấn công.","Chặn hoàn toàn sự tổng hợp lysozyme ở nước bọt.","Opsonin hóa — đánh dấu 'làm ngon miệng' giúp thụ thể $Fc$ và thụ thể bổ thể trên màng đại thực bào/bạch cầu trung tính bám chặt và thực bào vi khuẩn hiệu quả hơn gấp hàng trăm lần.","Biến đổi vi khuẩn thành tế bào gốc đa năng."],"ans":2,"exp":"Opsonin hóa là cầu nối phân tử giữa kháng nguyên vi sinh vật (gắn phần Fab của IgG) với tế bào thực bào (nhờ phần Fc bám vào Fc-receptor)."},{"id":"MCQ-PH-145","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thủy sinh học - Nồng độ Oxy Hòa tan (DO) & Hô hấp Cá","q":"Khi nhiệt độ nước ao nuôi cá tăng lên từ $20^\\circ\\text{C}$ lên $34^\\circ\\text{C}$, cá thường bị ngạt và phải ngoi lên mặt nước đớp không khí vì hai tác động hiệp đồng nào?","opts":["Khi nhiệt độ nước tăng, độ hòa tan của $O_2$ trong nước GIẢM xuống, ĐỒNG THỜI tốc độ trao đổi chất và nhu cầu tiêu thụ $O_2$ của động vật biến nhiệt (cá) lại TĂNG vọt theo nhiệt độ.","Nhiệt độ cao làm nước biển tách thành $H_2$ bay lên hết.","Nước ấm làm mang cá đông cứng hoàn toàn không mở được.","Cả độ hòa tan $O_2$ lẫn nhu cầu $O_2$ của cá đều giảm về bằng $0$."],"ans":0,"exp":"Độ tan chất khí trong nước tỉ lệ nghịch với nhiệt độ, trong khi tốc độ chuyển hóa sinh vật biến nhiệt tuân theo hệ số nhiệt $Q_{10} \\approx 2-3$ $\\rightarrow$ khủng hoảng cung-cầu $O_2$."},{"id":"MCQ-PH-146","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quang hợp Thực vật - Trạng thái Phosphoryl hóa Vòng","q":"Khi tế bào thực vật cần tỷ lệ $ATP / NADPH$ CAO hơn mức cố định thông thường ($3\\text{ ATP} : 2\\text{ NADPH}$) để chạy các hoạt động tổng hợp bổ sung (như chu trình $C_4$ hay ngăn photorespiration), hệ thống màng tilacoit kích hoạt mạnh quá trình nào ở pha sáng?","opts":["Dừng chuỗi vận chuyển electron trên màng tilacoit.","Phosphoryl hóa quang hợp VÒNG (Cyclic electron flow) chỉ sử dụng hệ quang hóa I (PS I), quay vòng electron qua ferredoxin và phức hệ cytochrome $b_6 f$ để bơm $H^+$ tạo thêm <strong>ATP</strong> mà KHÔNG sinh <strong>NADPH</strong> và KHÔNG giải phóng <strong>$O_2$</strong>.","Ngắt kết nối hoàn toàn PS I và chỉ cho PS II hoạt động tạo thật nhiều $O_2$.","Kích thích ty thể chuyển glucozơ thành axit lactic."],"ans":1,"exp":"Dòng electron không vòng tạo cố định $\\approx 1.28-1.5\\text{ ATP}$ trên $1\\text{ NADPH}$, chưa đủ cho chu trình Calvin ($1.5$) lẫn bơm $C_4$ ($2.5$); dòng vòng qua PS I giúp bù đắp lượng ATP thiếu hụt."},{"id":"MCQ-PH-147","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh lý Tim mạch - Phản xạ Áp thụ thể (Baroreceptor)","q":"Khi một người đứng dậy đột ngột làm máu dồn xuống tĩnh mạch chân khiến huyết áp động mạch cảnh giảm thoáng qua, chuỗi phản ứng điều hòa nhanh qua cung phản xạ áp thụ thể (xoang cảnh & quai động mạch chủ) diễn ra theo trình tự nào để khôi phục huyết áp?","opts":["Tăng tiết ANP từ tâm nhĩ làm mất muối qua thận ngay lập tức.","Áp thụ thể tăng xung kích thích dây thần kinh phế vị (đối giao cảm) làm giảm nhịp tim xuống $30$ nhịp/phút.","Áp thụ thể giảm tần số phát xung về hành não $\\rightarrow$ tăng trương lực thần kinh GIAO CẢM và giảm đối giao cảm $\\rightarrow$ tăng nhịp tim, tăng lực co bóp cơ tim và co tiểu động mạch/tĩnh mạch $\\rightarrow$ nâng huyết áp về bình thường.","Tuyến giáp ngừng tiết $T_3, T_4$ làm giãn mạch ngoại vi."],"ans":2,"exp":"Phản xạ áp thụ thể kiểm soát huyết áp ngắn hạn theo từng giây qua trung khu vận mạch hành não; tụt huyết áp giảm sự ức chế lên giao cảm $\\rightarrow$ bùng phát giao cảm bù trừ."},{"id":"MCQ-PH-148","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Sinh thái Tác động Lên-Xuống (Trophic Cascade)","q":"Ở vùng ven biển Thái Bình Dương, hệ sinh thái rừng tảo bẹ (*Kelp*) bị suy tàn biến thành 'hoang mạc nhím biển' ngay sau khi loài rái cá biển (*Enhydra lutris*) bị săn bắt quá mức. Chuỗi nhân quả sinh thái nào giải thích hiện tượng này?","opts":["Tảo bẹ ăn thịt rái cá biển nên thiếu rái cá thì tảo bị chết đói.","Nhím biển cộng sinh làm rừng tảo bẹ mọc cao gấp đôi khi rái cá mất đi.","Biến đổi pH do rái cá thở gây ra.","Rái cá biển là loài chủ chốt khống chế quần thể nhím biển; mất rái cá làm nhím biển bùng nổ ăn trụi rừng tảo bẹ $\\rightarrow$ hiện tượng thác dinh dưỡng từ trên xuống (Top-down trophic cascade)."],"ans":3,"exp":"Tác động kiểm soát từ bậc dinh dưỡng đỉnh xuống các bậc dưới: rái cá ($+$ gián tiếp với tảo bẹ) ngăn nhím biển phá hủy hệ sinh thái tảo bẹ đa dạng."},{"id":"MCQ-PH-149","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thực vật & Đáp ứng Miễn dịch Thực vật (SAR)","q":"Khi một lá cây bị nhiễm virus cục bộ và xuất hiện phản ứng quá mẫn (tế bào quanh vết nhiễm tự chết để cô lập mầm bệnh), tín hiệu axit salicylic ($SA$) hoặc metyl salicylat được dẫn truyền lên toàn cây giúp các lá lành phía trên tăng đề kháng lâu dài chống nhiều mầm bệnh khác nhau gọi là:","opts":["Sự rụng lá theo mùa.","Quá trình hướng trọng lực âm.","Cộng sinh nốt sần vi khuẩn cố định đạm.","Kháng tập nhiễm toàn thân (Systemic Acquired Resistance - SAR)."],"ans":3,"exp":"SAR là cơ chế miễn dịch hệ thống đặc trưng ở thực vật dựa trên tín hiệu axit salicylic kích hoạt các gen PR (Pathogenesis-Related) khắp cơ thể cây."},{"id":"MCQ-PH-150","topic":"physiology","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điều hòa Tiết Axit Dạ dày & Bệnh lý Loét dạ dày","q":"Tại niêm mạc dạ dày người, 3 chất trung gian nội tại cùng phối hợp kích thích tế bào thành (Parietal cell) bơm $H^+$ qua bơm proton $H^+/K^+$-ATPase vào lòng dạ dày tạo pH rất axit ($1.5-2.0$) là những chất nào?","opts":["Adrenalin, Melatonin và Thyroxine.","Auxin, Etilen và Cytokinin.","Acetylcholine (từ dây phế vị), Gastrin (từ tế bào G hang vị) và Histamine (từ tế bào giống ưa crom $ECL$).","Secretin, Insulin và Glucagon."],"ans":2,"exp":"Đây là cơ sở của các thuốc điều trị loét dạ dày hiện đại: thuốc kháng thụ thể $H_2$ (chặn Histamine) và thuốc ức chế bơm proton PPI (như Omeprazole khóa $H^+/K^+$-ATPase)."}];
